export default {

  "setup_and_security": {
    "objects": [
      {"name":"RegulatoryAuthority","type":"standard","domain":"setup_and_security","description":"Represents a government agency or department that defines and enforces regulatory requirements for licenses, permits, or independent inspections. The record captures its Name, Description, AuthorityType, Status, and JurisdictionLevel, and RegulatoryAuthority is enabled for Field Audit Trail.","fields":[{"name":"Name","type":"Text","description":"Display name of the regulatory authority, such as Department of Building Inspection"},{"name":"Description","type":"LongTextArea","description":"Summary of the authority's jurisdiction, responsibilities, and scope of oversight"},{"name":"AuthorityType","type":"Picklist","description":"Categorizes the authority by function such as Licensing, Inspection, or Regulatory Enforcement"},{"name":"Status","type":"Picklist","description":"Indicates whether the regulatory authority is active or inactive"},{"name":"JurisdictionLevel","type":"Picklist","description":"Geographic scope of the authority such as Federal, State, County, or Municipal"}],"relationships":[{"target":"RegulatoryAuthorizationType","type":"parent","description":"Owns the authorization types (licenses and permits) that this authority issues"},{"target":"RegulatoryCode","type":"parent","description":"Owns the regulatory codes that define compliance standards within this authority's jurisdiction"}]},
      {"name":"BusinessType","type":"standard","domain":"setup_and_security","description":"Defines a category of business and the activities that the business performs for licensing and permitting purposes. The record captures Name, Description, Status, and IndustryCode, and BusinessType is enabled for Field Audit Trail.","fields":[{"name":"Name","type":"Text","description":"Display name of the business type such as Salon, Restaurant, or Construction Contractor"},{"name":"Description","type":"LongTextArea","description":"Detailed description of the business category and its regulatory requirements"},{"name":"Status","type":"Picklist","description":"Indicates whether the business type is actively tracked by the regulatory authority"},{"name":"IndustryCode","type":"Text","description":"Industry classification code such as NAICS or SIC code associated with this business type"}],"relationships":[{"target":"BusRegAuthorizationType","type":"parent","description":"Maps this business type to required regulatory authorization types through junction records"}]},
      {"name":"AccountAccountRelation","type":"standard","domain":"setup_and_security","description":"Relates one Account record to another Account record through AccountId and RelatedAccountId. It records the Name, RelationshipType, StartDate, and EndDate for the relationship and is enabled for Field Audit Trail.","fields":[{"name":"Name","type":"Text","description":"Name identifying this account-to-account relationship"},{"name":"AccountId","type":"Lookup","description":"Reference to the primary account in the relationship"},{"name":"RelatedAccountId","type":"Lookup","description":"Reference to the related account in the relationship"},{"name":"RelationshipType","type":"Picklist","description":"Type of relationship such as Parent, Subsidiary, Partner, or Affiliated"},{"name":"StartDate","type":"Date","description":"Date when the relationship between the two accounts became effective"},{"name":"EndDate","type":"Date","description":"Date when the relationship ended or is expected to end"}],"relationships":[{"target":"Account","type":"lookup","description":"Links to the primary account in the relationship"},{"target":"Account","type":"lookup","description":"Links to the related account in the relationship"}]},
      {"name":"ContactContactRelation","type":"standard","domain":"setup_and_security","description":"Represents a relationship between a Contact and another Contact through ContactId and RelatedContactId. It records the Name, RelationshipType, and IsActive status and is enabled for Field Audit Trail.","fields":[{"name":"Name","type":"Text","description":"Name identifying this contact-to-contact relationship"},{"name":"ContactId","type":"Lookup","description":"Reference to the first contact in the relationship"},{"name":"RelatedContactId","type":"Lookup","description":"Reference to the second contact in the relationship"},{"name":"RelationshipType","type":"Picklist","description":"Nature of the relationship such as Spouse, Parent, Child, Sibling, or Guardian"},{"name":"IsActive","type":"Checkbox","description":"Indicates whether this contact relationship is currently active"}],"relationships":[{"target":"Contact","type":"lookup","description":"Links to the first contact in the relationship"},{"target":"Contact","type":"lookup","description":"Links to the second related contact in the relationship"}]},
      {"name":"PartyRelationshipGroup","type":"standard","domain":"setup_and_security","description":"Defines a group of related parties, such as a household or another group used to organize relationships among constituents. It records the Name, GroupType, Description, and Status and is enabled for Field Audit Trail.","fields":[{"name":"Name","type":"Text","description":"Display name for the relationship group such as Smith Household or Doe Family Trust"},{"name":"GroupType","type":"Picklist","description":"Category of the group such as Household, Trust, Legal Entity, or Organization"},{"name":"Description","type":"LongTextArea","description":"Detailed description of the group's composition and purpose"},{"name":"Status","type":"Picklist","description":"Indicates whether the group is actively tracked"}],"relationships":[{"target":"PartyRoleRelation","type":"parent","description":"Contains member records defining who belongs to the group and their roles"}]},
      {"name":"PartyRoleRelation","type":"standard","domain":"setup_and_security","description":"Associates a related account with a PartyRelationshipGroup and identifies the account’s RoleType in that group. It records the Name, PartyRelationshipGroupId, RelatedAccountId, StartDate, and EndDate and is enabled for Field Audit Trail.","fields":[{"name":"Name","type":"Text","description":"Descriptive name for this role assignment within the group"},{"name":"PartyRelationshipGroupId","type":"Lookup","description":"Reference to the party relationship group this member belongs to"},{"name":"RelatedAccountId","type":"Lookup","description":"Reference to the account representing the individual in this group"},{"name":"RoleType","type":"Picklist","description":"The role this individual plays in the group such as Head of Household, Dependent, or Guardian"},{"name":"StartDate","type":"Date","description":"Date when the individual became a member of the group"},{"name":"EndDate","type":"Date","description":"Date when the individual's membership in the group ended"}],"relationships":[{"target":"PartyRelationshipGroup","type":"lookup","description":"Links this member to the party relationship group they belong to"},{"target":"Account","type":"lookup","description":"Identifies the individual account assigned to this group role"}]}
    ]
  },

  "common_features": {
    "objects": [
      {"name":"ActionPlanBaseTemplateAsgn","type":"standard","domain":"common_features","description":"ActionPlanBaseTemplateAsgn associates an Action Plan Template with a base template and records whether the assignment is active. Its fields include Name, ActionPlanTemplateId, BaseTemplateId, and IsActive, and the object supports Field Audit Trail in Public Sector Solutions.","fields":[{"name":"Name","type":"Text","description":"Descriptive name for this base template assignment"},{"name":"ActionPlanTemplateId","type":"Lookup","description":"Reference to the action plan template being assigned to a base template"},{"name":"BaseTemplateId","type":"Lookup","description":"Reference to the base template that serves as the foundation for this assignment"},{"name":"IsActive","type":"Checkbox","description":"Indicates whether this base template assignment is currently active"}],"relationships":[{"target":"ActionPlanTemplate","type":"lookup","description":"Links to the specific action plan template used in this assignment"}]},
      {"name":"ActionPlanTemplateAssignment","type":"standard","domain":"common_features","description":"ActionPlanTemplateAssignment assigns an Action Plan Template to a target object type and can scope the assignment to a record type. Its fields include Name, ActionPlanTemplateId, TargetObjectType, and RecordTypeId, and the object supports Field Audit Trail in Public Sector Solutions.","fields":[{"name":"Name","type":"Text","description":"Name identifying this template-to-record type assignment"},{"name":"ActionPlanTemplateId","type":"Lookup","description":"Reference to the action plan template being assigned"},{"name":"TargetObjectType","type":"Text","description":"API name of the object this template applies to such as BusinessLicenseApplication or Visit"},{"name":"RecordTypeId","type":"Lookup","description":"Reference to the specific record type this template is assigned to, if applicable"}],"relationships":[{"target":"ActionPlanTemplate","type":"lookup","description":"Links to the action plan template used for this assignment"}]},
      {"name":"DocumentChecklistItem","type":"standard","domain":"common_features","description":"DocumentChecklistItem tracks a required or submitted document associated with a parent record. It stores the Name, ParentRecordId, DocumentTypeId, Status, ReviewDate, and Comments used to identify, classify, review, and document the checklist item.","fields":[{"name":"Name","type":"Text","description":"Name of the document checklist item such as Proof of Identity or Business Registration Certificate"},{"name":"ParentRecordId","type":"Lookup","description":"Reference to the parent record this document supports, such as a license application or benefit application"},{"name":"DocumentTypeId","type":"Lookup","description":"Reference to the document type that categorizes this checklist item"},{"name":"Status","type":"Picklist","description":"Current status of the document such as Required, Submitted, Under Review, Approved, or Rejected"},{"name":"ReviewDate","type":"Date","description":"Date when the document was last reviewed by a caseworker or intake officer"},{"name":"Comments","type":"LongTextArea","description":"Reviewer comments or notes about the submitted document"}],"relationships":[{"target":"DocumentType","type":"lookup","description":"Classifies this checklist item by document category for routing and validation"},{"target":"BusinessLicenseApplication","type":"lookup","description":"Links to a license application when this document supports a licensing workflow"}]},
      {"name":"OmniAssessmentTask","type":"standard","domain":"common_features","description":"OmniAssessmentTask stores an assessment task and connects the assessment questions and Omniscript conditional logic used in a Dynamic Assessment. Its fields include Name, AssessmentId, Status, ActionPlanId, and ComplianceStatus, allowing the task to be associated with an assessment and an Action Plan.","fields":[{"name":"Name","type":"Text","description":"Descriptive name for the assessment task such as Fire Safety Inspection or Income Verification"},{"name":"AssessmentId","type":"Lookup","description":"Reference to the parent assessment this task belongs to"},{"name":"Status","type":"Picklist","description":"Current status of the task such as Not Started, In Progress, or Completed"},{"name":"ActionPlanId","type":"Lookup","description":"Reference to the action plan that contains this assessment task"},{"name":"ComplianceStatus","type":"Picklist","description":"Overall compliance result: Pass, Fail, NA, or Issue"}],"relationships":[{"target":"Assessment","type":"lookup","description":"Links to the parent assessment record containing this task"},{"target":"ActionPlan","type":"lookup","description":"Associates this assessment task with the action plan driving the workflow"}]},
      {"name":"Assessment","type":"standard","domain":"common_features","description":"Assessment represents an assessment conducted for an account, case, application, visit, or other supported context in Public Sector Solutions. Its fields include Name, AccountId, CaseId, Status, AssessmentType, and CompletedDate to identify the assessment, its context, type, progress, and completion.","fields":[{"name":"Name","type":"Text","description":"Descriptive name identifying this assessment instance"},{"name":"AccountId","type":"Lookup","description":"Reference to the constituent account being assessed"},{"name":"CaseId","type":"Lookup","description":"Reference to the case record associated with this assessment"},{"name":"Status","type":"Picklist","description":"Current status such as In Progress, Completed, or Archived"},{"name":"AssessmentType","type":"Picklist","description":"Category of assessment such as Eligibility, Compliance, Investigation, or Intake"},{"name":"CompletedDate","type":"DateTime","description":"Date and time when the assessment was completed"}],"relationships":[{"target":"Account","type":"lookup","description":"Links the assessment to the constituent being evaluated"},{"target":"Case","type":"lookup","description":"Associates this assessment with a specific case for investigation or intake"}]},
      {"name":"AssessmentQuestion","type":"standard","domain":"common_features","description":"AssessmentQuestion defines a question used to collect information through Discovery Framework and Dynamic Assessments. It stores Name, QuestionText, DataType, Category, IsActive, and ResponseValues so administrators can classify the question, define its response format, and make it available for use.","fields":[{"name":"Name","type":"Text","description":"Short name for the assessment question such as Fire Extinguishers Present or Area of Establishment"},{"name":"QuestionText","type":"LongTextArea","description":"The full text of the question displayed to the assessor or constituent"},{"name":"DataType","type":"Picklist","description":"Response data type: Checkbox, Date, DateTime, Decimal, Integer, Multi-select, Radio, Select, Text, Text Area, or Time"},{"name":"Category","type":"Picklist","description":"Logical grouping for the question such as Demographic, Financial, Fire Safety Inspection, or Public Safety Complaint"},{"name":"IsActive","type":"Checkbox","description":"Indicates whether this question is available for use in Omniscript forms"},{"name":"ResponseValues","type":"LongTextArea","description":"Allowed response values for Radio, Multi-select, and Select data types, entered on separate lines"}],"relationships":[{"target":"AssessmentQuestionVersion","type":"parent","description":"Contains versioned instances of this question for tracking changes over time"},{"target":"RegulatoryCodeUse","type":"parent","description":"Links question versions to applicable regulatory codes for inspection compliance"}]},
      {"name":"AssessmentQuestionResponse","type":"standard","domain":"common_features","description":"AssessmentQuestionResponse stores an answer to an assessment question and relates it to the applicable assessment and question. Its fields include Name, AssessmentId, AssessmentQuestionId, ResponseValue, ComplianceStatus, and ResponseValueScore, supporting response capture, compliance evaluation, and scoring.","fields":[{"name":"Name","type":"Text","description":"Auto-generated name for this response record"},{"name":"AssessmentId","type":"Lookup","description":"Reference to the parent assessment containing this response"},{"name":"AssessmentQuestionId","type":"Lookup","description":"Reference to the question being answered"},{"name":"ResponseValue","type":"Text","description":"The actual response provided by the assessor or constituent"},{"name":"ComplianceStatus","type":"Picklist","description":"Regulatory compliance result: Pass, Fail, NA, or Issue"},{"name":"ResponseValueScore","type":"Number","description":"Numeric score assigned to this response for quantitative evaluations"}],"relationships":[{"target":"Assessment","type":"lookup","description":"Links this response to its parent assessment"},{"target":"AssessmentQuestion","type":"lookup","description":"Identifies which question this response answers"},{"target":"RegulatoryCodeViolation","type":"lookup","description":"Links to the violation record automatically created when compliance status is Fail"}]},
      {"name":"AssessmentQuestionVersion","type":"standard","domain":"common_features","description":"AssessmentQuestionVersion stores a version of an Assessment Question so question definitions can be maintained over time. Its fields include Name, AssessmentQuestionId, VersionNumber, and IsActive to identify the parent question, version sequence, and active version.","fields":[{"name":"Name","type":"Text","description":"Version identifier for this assessment question instance"},{"name":"AssessmentQuestionId","type":"Lookup","description":"Reference to the parent assessment question"},{"name":"VersionNumber","type":"Number","description":"Sequential version number for this question version"},{"name":"IsActive","type":"Checkbox","description":"Indicates whether this version is the currently active version of the question"}],"relationships":[{"target":"AssessmentQuestion","type":"lookup","description":"Links back to the parent assessment question this version belongs to"},{"target":"RegulatoryCodeUse","type":"child","description":"Regulatory code use records associate this question version with applicable compliance codes"}]},
      {"name":"InteractionSummary","type":"standard","domain":"common_features","description":"InteractionSummary stores notes and details from a meeting or conversation associated with an interaction. Its fields include Name, InteractionId, NoteContent, InteractionNotePublished, InteractionType, and InteractionDate, and publishing the note prevents further edits.","fields":[{"name":"Name","type":"Text","description":"Title or subject of the interaction summary"},{"name":"InteractionId","type":"Lookup","description":"Reference to the parent interaction record"},{"name":"NoteContent","type":"RichTextArea","description":"Rich text body containing meeting notes, observations, and action items"},{"name":"InteractionNotePublished","type":"Checkbox","description":"When true, the note is locked and cannot be further edited, serving as official evidence"},{"name":"InteractionType","type":"Picklist","description":"Type of interaction such as Phone Call, In-Person Meeting, Home Visit, or Email"},{"name":"InteractionDate","type":"DateTime","description":"Date and time when the interaction took place"}],"relationships":[{"target":"Interaction","type":"lookup","description":"Links to the parent interaction record that groups related summaries"},{"target":"Account","type":"lookup","description":"Associates the interaction summary with the constituent's account"}]}
    ]
  },

  "licensing_and_permitting": {
    "objects": [
      {"name":"BusinessLicenseApplication","type":"standard","domain":"licensing_and_permitting","description":"BusinessLicenseApplication stores a business request for a license or permit, including the applicant AccountId, ApplicationType, ApplicationStatus, and SubmittedDate. RegulatoryAuthorizationTypeId and RegulatoryAuthorityId identify the requested authorization and responsible authority.","fields":[{"name":"Name","type":"Text","description":"Application identifier or name"},{"name":"AccountId","type":"Lookup","description":"Reference to the business account submitting the application"},{"name":"ApplicationStatus","type":"Picklist","description":"Current status in the approval workflow: Submitted, Under Review, Pending Inspection, Approved, Denied"},{"name":"ApplicationType","type":"Picklist","description":"Type of license or permit being applied for"},{"name":"SubmittedDate","type":"DateTime","description":"Date and time when the application was submitted through the portal"},{"name":"RegulatoryAuthorizationTypeId","type":"Lookup","description":"Reference to the authorization type being requested"},{"name":"RegulatoryAuthorityId","type":"Lookup","description":"Reference to the regulatory authority that oversees this license type"}],"relationships":[{"target":"Account","type":"lookup","description":"Links the application to the business account of the applicant"},{"target":"RegulatoryAuthorizationType","type":"lookup","description":"Identifies the specific license or permit type requested"},{"target":"RegulatoryAuthority","type":"lookup","description":"Associates the application with the issuing regulatory authority"},{"target":"BusinessLicense","type":"child","description":"When approved, the application results in an issued business license record"}]},
      {"name":"BusinessLicense","type":"standard","domain":"licensing_and_permitting","description":"BusinessLicense represents a license or permit issued to an account. It records the LicenseType, Status, EffectiveDate, ExpirationDate, and associated RegulatoryAuthorizationTypeId.","fields":[{"name":"Name","type":"Text","description":"Display name or license number for the issued license"},{"name":"AccountId","type":"Lookup","description":"Reference to the account that holds this license"},{"name":"LicenseType","type":"Picklist","description":"Category of the issued license such as Business, Professional, or Occupational"},{"name":"Status","type":"Picklist","description":"Current status: Active, Suspended, Revoked, or Expired"},{"name":"EffectiveDate","type":"Date","description":"Date when the license becomes effective"},{"name":"ExpirationDate","type":"Date","description":"Date when the license expires and requires renewal"},{"name":"RegulatoryAuthorizationTypeId","type":"Lookup","description":"Reference to the authorization type this license represents"}],"relationships":[{"target":"Account","type":"lookup","description":"Links the license to the business or individual account that holds it"},{"target":"RegulatoryAuthorizationType","type":"lookup","description":"Identifies the specific type of regulatory authorization this license represents"},{"target":"BusinessLicenseApplication","type":"lookup","description":"Links back to the application that resulted in this license issuance"}]},
      {"name":"RegulatoryAuthorizationType","type":"standard","domain":"licensing_and_permitting","description":"RegulatoryAuthorizationType defines a type of license or permit administered by a regulatory authority. It records the RegulatoryAuthorityId, AuthorizationCategory, Description, and Status for the authorization type.","fields":[{"name":"Name","type":"Text","description":"Name of the authorization type such as Salon Establishment License or Fire Permit"},{"name":"RegulatoryAuthorityId","type":"Lookup","description":"Reference to the regulatory authority that issues this type of authorization"},{"name":"AuthorizationCategory","type":"Picklist","description":"Broad category such as Business License, Individual License, or Permit"},{"name":"Description","type":"LongTextArea","description":"Detailed description of what this authorization covers and its requirements"},{"name":"Status","type":"Picklist","description":"Whether this authorization type is currently active and available for applications"}],"relationships":[{"target":"RegulatoryAuthority","type":"lookup","description":"Links to the authority responsible for issuing this type of authorization"},{"target":"BusRegAuthorizationType","type":"parent","description":"Junction records mapping this authorization type to applicable business types"}]},
      {"name":"BusRegAuthorizationType","type":"standard","domain":"licensing_and_permitting","description":"BusRegAuthorizationType maps a BusinessTypeId to a RegulatoryAuthorizationTypeId. IsRequired indicates whether the mapped license or permit is required for that business type.","fields":[{"name":"Name","type":"Text","description":"Auto-generated name combining the business type and authorization type"},{"name":"BusinessTypeId","type":"Lookup","description":"Reference to the business type that requires this authorization"},{"name":"RegulatoryAuthorizationTypeId","type":"Lookup","description":"Reference to the regulatory authorization type required for this business type"},{"name":"IsRequired","type":"Checkbox","description":"Indicates whether this authorization is mandatory for the business type"}],"relationships":[{"target":"BusinessType","type":"lookup","description":"Links to the business type that requires this specific authorization"},{"target":"RegulatoryAuthorizationType","type":"lookup","description":"Links to the regulatory authorization type required by this business type"}]},
      {"name":"BusRegAuthTypeDependency","type":"standard","domain":"licensing_and_permitting","description":"BusRegAuthTypeDependency defines a dependency between a parent BusRegAuthorizationTypeId and a DependentBusRegAuthorizationTypeId. DependencyType characterizes the relationship between the two business regulatory authorization types.","fields":[{"name":"Name","type":"Text","description":"Name identifying this dependency relationship"},{"name":"BusRegAuthorizationTypeId","type":"Lookup","description":"Reference to the parent authorization type that must be obtained first"},{"name":"DependentBusRegAuthorizationTypeId","type":"Lookup","description":"Reference to the dependent authorization type that requires the parent"},{"name":"DependencyType","type":"Picklist","description":"Type of dependency such as Prerequisite or Corequisite"}],"relationships":[{"target":"BusRegAuthorizationType","type":"lookup","description":"Links to the parent authorization type that must be obtained first"},{"target":"BusRegAuthorizationType","type":"lookup","description":"Links to the dependent authorization type requiring the parent"}]},
      {"name":"RegulatoryTrxnFee","type":"standard","domain":"licensing_and_permitting","description":"RegulatoryTrxnFee represents a fee associated with a regulatory action. It stores the responsible AccountId, Status, EffectiveDateTime, DueDateTime, and Comments, with the due date maintained on this parent fee record.","fields":[{"name":"Name","type":"Text","description":"Identifier for the regulatory transaction fee"},{"name":"AccountId","type":"Lookup","description":"Reference to the account responsible for paying this fee"},{"name":"Status","type":"Picklist","description":"Current fee status: Due, Paid, Waived, or Overdue"},{"name":"EffectiveDateTime","type":"DateTime","description":"Date and time from when the transaction fee is applicable"},{"name":"DueDateTime","type":"DateTime","description":"Date and time by which the fee must be paid"},{"name":"Comments","type":"LongTextArea","description":"Context or explanation for the fee"}],"relationships":[{"target":"Account","type":"lookup","description":"Links to the account responsible for this fee"},{"target":"BusinessLicenseApplication","type":"lookup","description":"Associates the fee with a specific license application"},{"target":"RegulatoryTrxnFeeItem","type":"parent","description":"Contains line items that break down the fee into individual amounts"}]},
      {"name":"RegulatoryTrxnFeeItem","type":"standard","domain":"licensing_and_permitting","description":"RegulatoryTrxnFeeItem is an individual line item belonging to a RegulatoryTrxnFeeId. It records the Amount, Status, and optional Comments for that fee component and does not contain a due-date field.","fields":[{"name":"Name","type":"Text","description":"Name describing the fee line item such as Application Fee or Inspection Fee"},{"name":"RegulatoryTrxnFeeId","type":"Lookup","description":"Reference to the parent regulatory transaction fee"},{"name":"Amount","type":"Currency","description":"The monetary amount for this individual fee line item"},{"name":"Status","type":"Picklist","description":"Status of this line item: Pending, Paid, or Waived"},{"name":"Comments","type":"LongTextArea","description":"Additional context or description for this fee item"}],"relationships":[{"target":"RegulatoryTrxnFee","type":"lookup","description":"Links this line item to the parent regulatory transaction fee"}]},
      {"name":"AuthApplicationAsset","type":"standard","domain":"licensing_and_permitting","description":"AuthApplicationAsset maps an AssetId to a BusinessLicenseApplicationId, associating an asset with an authorization application. Status records the state of that application-to-asset relationship; the object does not relate the asset to an issued BusinessLicense.","fields":[{"name":"Name","type":"Text","description":"Name identifying this asset-to-application association"},{"name":"BusinessLicenseApplicationId","type":"Lookup","description":"Reference to the license application this asset is associated with"},{"name":"AssetId","type":"Lookup","description":"Reference to the asset record linked to the application"},{"name":"Status","type":"Picklist","description":"Status of the asset association such as Active, Pending, or Removed"}],"relationships":[{"target":"BusinessLicenseApplication","type":"lookup","description":"Links the asset to a specific license application"},{"target":"Asset","type":"lookup","description":"Links to the asset record covered by the license"}]},
      {"name":"AuthApplicationPlace","type":"standard","domain":"licensing_and_permitting","description":"AuthApplicationPlace maps a PlaceId to a BusinessLicenseApplicationId, associating a location with an authorization application. Status records the state of that application-to-location relationship; the object does not relate the place to an issued BusinessLicense.","fields":[{"name":"Name","type":"Text","description":"Name identifying this place-to-application association"},{"name":"BusinessLicenseApplicationId","type":"Lookup","description":"Reference to the license application this location is associated with"},{"name":"PlaceId","type":"Lookup","description":"Reference to the location or address record linked to the application"},{"name":"Status","type":"Picklist","description":"Status of the location association"}],"relationships":[{"target":"BusinessLicenseApplication","type":"lookup","description":"Links the location to a specific license application"},{"target":"Location","type":"lookup","description":"Links to the physical location record covered by the license"}]},
      {"name":"RegAuthorizationTypeProduct","type":"standard","domain":"licensing_and_permitting","description":"RegAuthorizationTypeProduct defines a relationship between a RegulatoryAuthorizationTypeId and a ProductId representing Product2. It records the relationship name and Status and is not the source used by the Permits component to display business authorization requirements or dependencies.","fields":[{"name":"Name","type":"Text","description":"Name identifying this authorization-to-product mapping"},{"name":"RegulatoryAuthorizationTypeId","type":"Lookup","description":"Reference to the regulatory authorization type"},{"name":"ProductId","type":"Lookup","description":"Reference to the product or service covered by this authorization"},{"name":"Status","type":"Picklist","description":"Whether this product association is currently active"}],"relationships":[{"target":"RegulatoryAuthorizationType","type":"lookup","description":"Links to the authorization type that covers this product"},{"target":"Product2","type":"lookup","description":"Links to the specific product or service permitted under the authorization"}]},
      {"name":"PreliminaryApplicationRef","type":"standard","domain":"licensing_and_permitting","description":"PreliminaryApplicationRef represents a saved or preliminary application associated with an AccountId. It records the ApplicationType, Status, and SavedSessionId so a constituent can return to an unfinished application session.","fields":[{"name":"Name","type":"Text","description":"Reference identifier for the preliminary application"},{"name":"AccountId","type":"Lookup","description":"Reference to the constituent account that started the application"},{"name":"ApplicationType","type":"Picklist","description":"Type of application being drafted such as Business License or Individual License"},{"name":"Status","type":"Picklist","description":"Current status: Draft, Submitted, or Abandoned"},{"name":"SavedSessionId","type":"Text","description":"Reference to the Omniscript saved session for resuming the application"}],"relationships":[{"target":"Account","type":"lookup","description":"Links to the constituent who initiated the preliminary application"},{"target":"BusinessLicenseApplication","type":"lookup","description":"Links to the final application record once submitted"}]},
      {"name":"AuthLocationAccessSchedule","type":"standard","domain":"licensing_and_permitting","description":"AuthLocationAccessSchedule records an access window for an AuthApplicationPlaceId. DayOfWeek, StartTime, and EndTime describe when the authorization application location is available for access.","fields":[{"name":"Name","type":"Text","description":"Name identifying this access schedule entry"},{"name":"AuthApplicationPlaceId","type":"Lookup","description":"Reference to the authorized application place this schedule applies to"},{"name":"DayOfWeek","type":"Picklist","description":"Day of the week for this access window"},{"name":"StartTime","type":"DateTime","description":"Start time of the access window"},{"name":"EndTime","type":"DateTime","description":"End time of the access window"}],"relationships":[{"target":"AuthApplicationPlace","type":"lookup","description":"Links to the authorized location this access schedule belongs to"}]}
    ]
  },

  "inspections": {
    "objects": [
      {"name":"InspectionType","type":"standard","domain":"inspections","description":"Represents a configured type of inspection in Public Sector Solutions and identifies its Regulatory Authority, operational Status, and Inspection Frequency. Name and Description distinguish the inspection scenario, such as a health and safety or salon establishment inspection.","fields":[{"name":"Name","type":"Text","description":"Name of the inspection type such as Fire Safety Inspection or Health Code Inspection"},{"name":"Description","type":"LongTextArea","description":"Detailed description of what this inspection covers and its compliance standards"},{"name":"RegulatoryAuthorityId","type":"Lookup","description":"Reference to the regulatory authority that mandates this inspection type"},{"name":"Status","type":"Picklist","description":"Whether this inspection type is currently active"},{"name":"InspectionFrequency","type":"Picklist","description":"How often this inspection must be conducted: Annual, Semi-Annual, Quarterly, or On-Demand"}],"relationships":[{"target":"RegulatoryAuthority","type":"lookup","description":"Links to the authority that mandates and oversees this inspection type"},{"target":"InspectionAssessmentInd","type":"parent","description":"Contains the assessment indicators used during this type of inspection"}]},
      {"name":"InspectionAssessmentInd","type":"standard","domain":"inspections","description":"Associates an Assessment Indicator Definition with an Inspection Type for a fixed inspection. SortOrder controls the indicator's sequence within the inspection configuration.","fields":[{"name":"Name","type":"Text","description":"Name identifying this inspection assessment indicator link"},{"name":"InspectionTypeId","type":"Lookup","description":"Reference to the inspection type this indicator belongs to"},{"name":"AssessmentIndicatorDefinitionId","type":"Lookup","description":"Reference to the assessment indicator definition used in this inspection"},{"name":"SortOrder","type":"Number","description":"Display order of this indicator within the inspection checklist"}],"relationships":[{"target":"InspectionType","type":"lookup","description":"Links to the inspection type that includes this assessment indicator"},{"target":"AssessmentIndicatorDefinition","type":"lookup","description":"Links to the specific assessment measure used during inspections"}]},
      {"name":"RegulatoryCode","type":"standard","domain":"inspections","description":"Defines a specific compliance standard established by a Regulatory Authority. It stores the code's Name, Subject, Description, Type, effective date, and responsible RegulatoryAuthorityId.","fields":[{"name":"Name","type":"Text","description":"Code identifier such as 19.05 Fire Code or Section 14.3 Food Safety"},{"name":"Subject","type":"Text","description":"Subject area of the regulatory code such as Fire Prevention, Food Safety, or Building Safety"},{"name":"Description","type":"LongTextArea","description":"Full text of the regulatory requirement including specific compliance criteria"},{"name":"Type","type":"Picklist","description":"Classification of the code such as Section, Subsection, or Amendment"},{"name":"EffectiveFrom","type":"Date","description":"Date when this regulatory code became effective"},{"name":"RegulatoryAuthorityId","type":"Lookup","description":"Reference to the authority that established this code"}],"relationships":[{"target":"RegulatoryAuthority","type":"lookup","description":"Links to the regulatory authority that owns and enforces this code"},{"target":"RegulatoryCodeViolation","type":"parent","description":"Violations created when inspections find non-compliance with this code"}]},
      {"name":"RegulatoryCodeAssessmentInd","type":"standard","domain":"inspections","description":"Relates a Regulatory Code to an Assessment Indicator Definition used to measure compliance in a fixed inspection. Status indicates whether the relationship is available for use.","fields":[{"name":"Name","type":"Text","description":"Name identifying this regulatory code to assessment indicator link"},{"name":"RegulatoryCodeId","type":"Lookup","description":"Reference to the regulatory code being assessed"},{"name":"AssessmentIndicatorDefinitionId","type":"Lookup","description":"Reference to the assessment indicator used to evaluate this code"},{"name":"Status","type":"Picklist","description":"Whether this link is currently active"}],"relationships":[{"target":"RegulatoryCode","type":"lookup","description":"Links to the regulatory compliance code being measured"},{"target":"AssessmentIndicatorDefinition","type":"lookup","description":"Links to the assessment indicator that evaluates compliance with this code"}]},
      {"name":"RegulatoryCodeUse","type":"standard","domain":"inspections","description":"Relates an Assessment Question Version to a Regulatory Code for Dynamic Assessments. This junction allows the applicable code to be presented with a Dynamic Assessment question, subject to the record's Status.","fields":[{"name":"Name","type":"Text","description":"Name identifying this regulatory code use record"},{"name":"AssessmentQuestionVersionId","type":"Lookup","description":"Reference to the assessment question version linked to this code"},{"name":"RegulatoryCodeId","type":"Lookup","description":"Reference to the regulatory code linked to this assessment question"},{"name":"Status","type":"Picklist","description":"Whether this code use record is active"}],"relationships":[{"target":"AssessmentQuestionVersion","type":"lookup","description":"Links to the versioned assessment question that evaluates this code"},{"target":"RegulatoryCode","type":"lookup","description":"Links to the regulatory code that this question assesses"}]},
      {"name":"RegulatoryCodeViolation","type":"standard","domain":"inspections","description":"Records a failure to comply with a Regulatory Code and can associate the violation with the Visit where it was identified. It captures Severity, ComplianceStatus, and DateIdentified for compliance follow-up.","fields":[{"name":"Name","type":"Text","description":"Description or identifier for this violation"},{"name":"RegulatoryCodeId","type":"Lookup","description":"Reference to the regulatory code that was violated"},{"name":"Severity","type":"Picklist","description":"Severity level: Minor Violation, Major Violation, or Critical Violation"},{"name":"ComplianceStatus","type":"Picklist","description":"Current compliance status: Open, Remediated, or Closed"},{"name":"VisitId","type":"Lookup","description":"Reference to the inspection visit where this violation was identified"},{"name":"DateIdentified","type":"Date","description":"Date when the violation was first identified"}],"relationships":[{"target":"RegulatoryCode","type":"lookup","description":"Links to the specific code that was violated"},{"target":"Visit","type":"lookup","description":"Links to the inspection visit where this violation was discovered"},{"target":"ViolationEnforcementAction","type":"parent","description":"Contains enforcement actions taken in response to this violation"}]},
      {"name":"ViolationEnforcementAction","type":"standard","domain":"inspections","description":"Records a compliance-officer action created in response to a Regulatory Code Violation. ActionType, Status, DueDate, and Description capture the nature and progress of the follow-up.","fields":[{"name":"Name","type":"Text","description":"Name or description of the enforcement action"},{"name":"RegulatoryCodeViolationId","type":"Lookup","description":"Reference to the violation that triggered this enforcement action"},{"name":"ActionType","type":"Picklist","description":"Type of enforcement action: Fine, Warning, Suspension, Revocation, or Remediation Required"},{"name":"Status","type":"Picklist","description":"Current status of the enforcement action: Pending, Active, Completed, or Appealed"},{"name":"DueDate","type":"Date","description":"Date by which the enforcement action must be completed or remediated"},{"name":"Description","type":"LongTextArea","description":"Detailed description of the enforcement action and its requirements"}],"relationships":[{"target":"RegulatoryCodeViolation","type":"lookup","description":"Links to the violation that prompted this enforcement action"},{"target":"RegulatoryTrxnFee","type":"child","description":"Fee records automatically generated for this enforcement action"}]},
      {"name":"ViolationType","type":"standard","domain":"inspections","description":"Defines a way in which a business or site can fail to comply with a Regulatory Code. Its Type, Severity, and Description support classification of violations recorded during inspections.","fields":[{"name":"Name","type":"Text","description":"Name of the violation type such as Fire extinguishers not present or Expired food storage"},{"name":"Type","type":"Picklist","description":"Broad classification such as Health and Safety, Fire Code, or Environmental"},{"name":"Severity","type":"Picklist","description":"Default severity level: Minor Violation, Major Violation, or Critical Violation"},{"name":"Description","type":"LongTextArea","description":"Detailed description of what constitutes this type of violation"}],"relationships":[{"target":"RegulatoryCodeViolation","type":"parent","description":"Violations reference this type to categorize the nature of the non-compliance"}]},
      {"name":"Visit","type":"standard","domain":"inspections","description":"Represents an onsite inspection Visit planned for an Account and assigned to a Visitor. It stores planned and actual timing, Status, and InspectionTypeId so Public Sector Solutions can schedule and track inspection activity.","fields":[{"name":"Name","type":"Text","description":"Name or identifier for the visit"},{"name":"AccountId","type":"Lookup","description":"Reference to the business account being visited"},{"name":"PlannedVisitStartTime","type":"DateTime","description":"Scheduled start date and time for the inspection visit"},{"name":"PlannedVisitEndTime","type":"DateTime","description":"Scheduled end date and time for the inspection visit"},{"name":"ActualVisitStartTime","type":"DateTime","description":"Actual start time recorded by the inspector"},{"name":"Status","type":"Picklist","description":"Current status: Planned, In Progress, Completed, or Cancelled"},{"name":"InspectionTypeId","type":"Lookup","description":"Reference to the type of inspection being conducted"},{"name":"VisitorId","type":"Lookup","description":"Reference to the inspector conducting the visit"}],"relationships":[{"target":"Account","type":"lookup","description":"Links to the business account being inspected"},{"target":"InspectionType","type":"lookup","description":"Identifies the category of inspection being conducted"},{"target":"Visitor","type":"lookup","description":"Links to the inspector record for the person conducting the visit"},{"target":"BusinessLicenseApplication","type":"lookup","description":"Associates the visit with the license application requiring inspection"}]},
      {"name":"Visitor","type":"standard","domain":"inspections","description":"Represents the user who is available for assignment to a Visit. The record associates the visitor with UserId and records the visitor's Status and Specialization; availability is checked through user list views in Salesforce Calendar rather than stored on the Visitor record.","fields":[{"name":"Name","type":"Text","description":"Full name of the inspector or visitor"},{"name":"UserId","type":"Lookup","description":"Reference to the Salesforce user record of the inspector"},{"name":"Status","type":"Picklist","description":"Current availability status: Available, On Assignment, or Inactive"},{"name":"Specialization","type":"Text","description":"Areas of inspection expertise such as Fire Safety, Health, or Building Code"}],"relationships":[{"target":"User","type":"lookup","description":"Links to the Salesforce user record for the inspector"},{"target":"Visit","type":"child","description":"Visits assigned to this inspector"}]}
    ]
  },

  "social_programs": {
    "objects": [
      {"name":"PublicProgram","type":"standard","domain":"social_programs","description":"PublicProgram represents a high-level social program offered to support constituent well-being, such as job readiness, housing services, refugee settlement, or child welfare. Its fields capture the program’s name, description, status, category, and start and end dates.","fields":[{"name":"Name","type":"Text","description":"Display name of the social program such as Job Readiness Program or Child Welfare Services"},{"name":"Description","type":"LongTextArea","description":"Summary of the program's purpose, eligibility requirements, and available services"},{"name":"Status","type":"Picklist","description":"Current status of the program: Active, Inactive, or Pilot"},{"name":"ProgramCategory","type":"Picklist","description":"Category such as Housing, Employment, Child Welfare, Elder Care, or Nutrition"},{"name":"StartDate","type":"Date","description":"Date when the program became available to constituents"},{"name":"EndDate","type":"Date","description":"Date when the program is scheduled to end, if applicable"}],"relationships":[{"target":"Benefit","type":"parent","description":"Contains the specific benefits available under this program"},{"target":"ProgramEnrollment","type":"parent","description":"Tracks constituent enrollment records for this program"}]},
      {"name":"CarePlan","type":"standard","domain":"social_programs","description":"CarePlan represents an individualized plan for coordinating a constituent’s goals, benefits, services, and action items. It associates the plan with an account and optional care plan template and tracks its status and start and end dates.","fields":[{"name":"Name","type":"Text","description":"Display name for the care plan"},{"name":"AccountId","type":"Lookup","description":"Reference to the constituent account this care plan serves"},{"name":"CarePlanTemplateId","type":"Lookup","description":"Reference to the template used to create this care plan"},{"name":"Status","type":"Picklist","description":"Current status: Draft, Active, On Hold, Completed, or Closed"},{"name":"StartDate","type":"Date","description":"Date when the care plan became active for the constituent"},{"name":"EndDate","type":"Date","description":"Expected or actual end date for the care plan"}],"relationships":[{"target":"Account","type":"lookup","description":"Links to the constituent receiving services under this care plan"},{"target":"CarePlanTemplate","type":"lookup","description":"Links to the template that defined the initial structure of this care plan"},{"target":"GoalAssignment","type":"parent","description":"Contains goal assignments tracking constituent progress toward defined outcomes"}]},
      {"name":"CarePlanTemplate","type":"standard","domain":"social_programs","description":"CarePlanTemplate provides a reusable, standardized starting point for care plans that address similar constituent circumstances. Its name, description, status, and category identify and organize the template for caseworker use.","fields":[{"name":"Name","type":"Text","description":"Display name for the care plan template such as Refugee Settlement Plan or Elder Care Plan"},{"name":"Description","type":"LongTextArea","description":"Description of the scenarios and populations this template is designed for"},{"name":"Status","type":"Picklist","description":"Whether this template is Active, Draft, or Retired"},{"name":"Category","type":"Picklist","description":"Category of care this template addresses such as Housing, Employment, or Health"}],"relationships":[{"target":"CarePlanTemplateBenefit","type":"parent","description":"Contains the default benefits included in care plans created from this template"},{"target":"CarePlanTemplateGoal","type":"parent","description":"Contains the default goals included in care plans created from this template"}]},
      {"name":"CarePlanTemplateBenefit","type":"standard","domain":"social_programs","description":"CarePlanTemplateBenefit adds a benefit to a care plan template so that plans created from the template can include the service. It identifies the template and benefit and uses SortOrder to control the benefit’s placement.","fields":[{"name":"Name","type":"Text","description":"Name identifying this template benefit association"},{"name":"CarePlanTemplateId","type":"Lookup","description":"Reference to the parent care plan template"},{"name":"BenefitId","type":"Lookup","description":"Reference to the benefit included in this template"},{"name":"SortOrder","type":"Number","description":"Display order of this benefit within the template"}],"relationships":[{"target":"CarePlanTemplate","type":"lookup","description":"Links to the care plan template this benefit belongs to"},{"target":"Benefit","type":"lookup","description":"Links to the specific benefit included in the template"}]},
      {"name":"CarePlanTemplateGoal","type":"standard","domain":"social_programs","description":"CarePlanTemplateGoal adds a goal definition to a care plan template. It identifies the template and goal definition and uses SortOrder to control the goal’s placement.","fields":[{"name":"Name","type":"Text","description":"Name identifying this template goal association"},{"name":"CarePlanTemplateId","type":"Lookup","description":"Reference to the parent care plan template"},{"name":"GoalDefinitionId","type":"Lookup","description":"Reference to the goal definition included in this template"},{"name":"SortOrder","type":"Number","description":"Display order of this goal within the template"}],"relationships":[{"target":"CarePlanTemplate","type":"lookup","description":"Links to the care plan template this goal belongs to"},{"target":"GoalDefinition","type":"lookup","description":"Links to the specific goal definition included in the template"}]},
      {"name":"GoalDefinition","type":"standard","domain":"social_programs","description":"GoalDefinition represents a reusable top or intermediate objective that programs and care plans can support. It stores descriptive information, a parent goal definition for hierarchy, the goal type, and status.","fields":[{"name":"Name","type":"Text","description":"Name of the goal such as Secure Employment or Complete GED Program"},{"name":"Description","type":"LongTextArea","description":"Detailed description of the goal and the criteria for measuring success"},{"name":"ParentGoalDefinitionId","type":"Lookup","description":"Reference to a parent goal for creating hierarchical goal trees"},{"name":"GoalType","type":"Picklist","description":"Classification such as Top Goal, Intermediate Goal, or Milestone"},{"name":"Status","type":"Picklist","description":"Whether this goal definition is Active, Draft, or Retired"}],"relationships":[{"target":"GoalDefinition","type":"lookup","description":"Self-referential link to a parent goal for hierarchical structures"},{"target":"GoalAssignment","type":"parent","description":"Contains assignments linking this goal to individual constituents"}]},
      {"name":"GoalAssignment","type":"standard","domain":"social_programs","description":"GoalAssignment applies a goal definition to a specific care plan and tracks progress toward that objective. Its fields record the assignment’s status, target date, and completed date.","fields":[{"name":"Name","type":"Text","description":"Name identifying this goal assignment"},{"name":"GoalDefinitionId","type":"Lookup","description":"Reference to the goal being assigned"},{"name":"CarePlanId","type":"Lookup","description":"Reference to the care plan this goal is part of"},{"name":"Status","type":"Picklist","description":"Progress status: Not Started, In Progress, Achieved, or Discontinued"},{"name":"TargetDate","type":"Date","description":"Target date for achieving this goal"},{"name":"CompletedDate","type":"Date","description":"Actual date when the goal was achieved"}],"relationships":[{"target":"GoalDefinition","type":"lookup","description":"Links to the goal definition being tracked"},{"target":"CarePlan","type":"lookup","description":"Links to the care plan containing this goal assignment"}]},
      {"name":"Referral","type":"standard","domain":"social_programs","description":"Referral captures a request to connect a constituent with an agency, program, or service provider. It associates the referral with an account and records its type, status, referring organization, and authorization status.","fields":[{"name":"Name","type":"Text","description":"Identifier for the referral record"},{"name":"AccountId","type":"Lookup","description":"Reference to the constituent account being referred"},{"name":"ReferralType","type":"Picklist","description":"Type of referral such as Job Training, Housing, Nutrition, or Elder Care"},{"name":"Status","type":"Picklist","description":"Current status: Pending, Accepted, In Progress, Completed, or Declined"},{"name":"ReferringOrganization","type":"Text","description":"Name of the organization or agency making the referral"},{"name":"AuthorizationStatus","type":"Picklist","description":"Authorization status for provider referrals: Requested, Authorized, or Denied"}],"relationships":[{"target":"Account","type":"lookup","description":"Links to the constituent being referred for services"},{"target":"Case","type":"lookup","description":"Links to the case created from this referral"},{"target":"CarePlan","type":"lookup","description":"Links to the care plan associated with this referral"}]},
      {"name":"PublicComplaint","type":"standard","domain":"social_programs","description":"PublicComplaint records a reported health, safety, well-being, or other public concern. It identifies the complainant account and captures the complaint type, status, incident date, and description.","fields":[{"name":"Name","type":"Text","description":"Identifier for the public complaint"},{"name":"ComplainantAccountId","type":"Lookup","description":"Reference to the account of the person filing the complaint"},{"name":"Status","type":"Picklist","description":"Current status: Filed, Under Review, Investigated, Resolved, or Dismissed"},{"name":"ComplaintType","type":"Picklist","description":"Category such as Health, Safety, Welfare, Environmental, or Consumer"},{"name":"IncidentDate","type":"Date","description":"Date when the incident being complained about occurred"},{"name":"Description","type":"LongTextArea","description":"Detailed description of the complaint and the circumstances"}],"relationships":[{"target":"Account","type":"lookup","description":"Links to the complainant's account"},{"target":"ComplaintCase","type":"child","description":"Investigative cases created from screened complaints"}]},
      {"name":"ProgramEnrollment","type":"standard","domain":"social_programs","description":"ProgramEnrollment records a constituent’s enrollment in a PublicProgram and can associate that enrollment with a CarePlan. It tracks the account, enrollment date, and status; benefits are assigned separately through the Benefit Assignment object.","fields":[{"name":"Name","type":"Text","description":"Name identifying this program enrollment record"},{"name":"PublicProgramId","type":"Lookup","description":"Reference to the public program the constituent is enrolled in"},{"name":"AccountId","type":"Lookup","description":"Reference to the constituent account enrolled in the program"},{"name":"EnrollmentDate","type":"Date","description":"Date when the constituent was enrolled in the program"},{"name":"Status","type":"Picklist","description":"Enrollment status: Active, Completed, Withdrawn, or Waitlisted"},{"name":"CarePlanId","type":"Lookup","description":"Reference to the care plan through which enrollment occurred"}],"relationships":[{"target":"PublicProgram","type":"lookup","description":"Links to the social program the constituent is enrolled in"},{"target":"Account","type":"lookup","description":"Links to the constituent's account"},{"target":"CarePlan","type":"lookup","description":"Links to the care plan that initiated this enrollment"}]}
    ]
  },

  "benefit_management": {
    "objects": [
      {"name":"IndividualApplication","type":"standard","domain":"benefit_management","description":"Represents a constituent application for benefits, recertification, or a change-related review. Name, AccountId, ApplicationStatus, RecordTypeId, SubmittedDate, and ApplicationType identify the applicant, processing configuration, submission timing, and application state.","fields":[{"name":"Name","type":"Text","description":"Application identifier or name"},{"name":"AccountId","type":"Lookup","description":"Reference to the individual constituent's person account"},{"name":"ApplicationStatus","type":"Picklist","description":"Current status: Submitted, Under Review, Approved, Denied, or Pending Recertification"},{"name":"RecordTypeId","type":"Lookup","description":"Record type distinguishing Benefit Assistance from other application types"},{"name":"SubmittedDate","type":"DateTime","description":"Date and time when the application was submitted"},{"name":"ApplicationType","type":"Picklist","description":"Type of application such as Benefit Assistance, Individual License, or Social Insurance Claim"}],"relationships":[{"target":"Account","type":"lookup","description":"Links to the individual constituent's person account"},{"target":"BenefitAssignment","type":"parent","description":"Contains benefit assignments made to the applicant after approval"},{"target":"Claim","type":"child","description":"Social insurance claim records linked to this individual application"}]},
      {"name":"Benefit","type":"standard","domain":"benefit_management","description":"Represents a benefit offered through a program in Public Sector Solutions. Name, BenefitTypeId, ProgramId, Description, Status, and Amount identify its classification, program relationship, availability, and monetary value.","fields":[{"name":"Name","type":"Text","description":"Display name of the benefit such as Housing Assistance Voucher or Food Assistance Monthly Payment"},{"name":"BenefitTypeId","type":"Lookup","description":"Reference to the parent benefit type this benefit belongs to"},{"name":"ProgramId","type":"Lookup","description":"Reference to the associated public program"},{"name":"Description","type":"LongTextArea","description":"Detailed description of what this benefit provides and eligibility criteria"},{"name":"Status","type":"Picklist","description":"Whether this benefit is currently Active, Inactive, or Deprecated"},{"name":"Amount","type":"Currency","description":"Standard monetary amount for this benefit, if applicable"}],"relationships":[{"target":"BenefitType","type":"lookup","description":"Links to the benefit type that categorizes this benefit"},{"target":"PublicProgram","type":"lookup","description":"Links to the program this benefit is part of"},{"target":"BenefitAssignment","type":"parent","description":"Contains assignments of this benefit to eligible constituents"}]},
      {"name":"BenefitType","type":"standard","domain":"benefit_management","description":"Classifies benefits by their configured process and service characteristics. Name, ProcessCategory, ServiceClassification, Description, and Status describe the type and whether it is available for use.","fields":[{"name":"Name","type":"Text","description":"Display name of the benefit type such as Food Assistance or Housing Voucher"},{"name":"ProcessCategory","type":"Picklist","description":"High-level classification: Social Insurance, Tax Benefits, Subsidies, or Direct Assistance"},{"name":"ServiceClassification","type":"Text","description":"Detailed service classification for reporting and eligibility matching"},{"name":"Description","type":"LongTextArea","description":"Description of this category of benefits and general eligibility criteria"},{"name":"Status","type":"Picklist","description":"Whether this benefit type is Active or Inactive"}],"relationships":[{"target":"Benefit","type":"parent","description":"Contains the specific benefits categorized under this type"}]},
      {"name":"BenefitAssignment","type":"standard","domain":"benefit_management","description":"Represents an approved benefit assigned to an applicant or account. Name, BenefitId, IndividualApplicationId, AccountId, Amount, Frequency, Status, and RecertificationDueDate track the benefit, recipient, payment terms, assignment state, and next recertification deadline.","fields":[{"name":"Name","type":"Text","description":"Identifier for this benefit assignment"},{"name":"BenefitId","type":"Lookup","description":"Reference to the benefit being assigned"},{"name":"IndividualApplicationId","type":"Lookup","description":"Reference to the individual application that was approved"},{"name":"AccountId","type":"Lookup","description":"Reference to the constituent receiving the benefit"},{"name":"Amount","type":"Currency","description":"Monetary amount assigned for this benefit"},{"name":"Frequency","type":"Picklist","description":"Disbursement frequency: Weekly, Bi-Weekly, Monthly, Quarterly, or One-Time"},{"name":"Status","type":"Picklist","description":"Assignment status: Active, Suspended, Completed, or Pending Recertification"},{"name":"RecertificationDueDate","type":"Date","description":"Date by which the constituent must recertify eligibility"}],"relationships":[{"target":"Benefit","type":"lookup","description":"Links to the specific benefit being assigned"},{"target":"IndividualApplication","type":"lookup","description":"Links to the approved application"},{"target":"Account","type":"lookup","description":"Links to the constituent receiving this benefit"},{"target":"BenefitDisbursement","type":"parent","description":"Contains disbursement records tracking payments made for this assignment"}]},
      {"name":"BenefitAssignmentAdjustment","type":"standard","domain":"benefit_management","description":"Records a change to an existing Benefit Assignment, including the revised amount and when it takes effect. Name, BenefitAssignmentId, AdjustmentReason, NewAmount, and EffectiveDate preserve the assignment relationship and adjustment details.","fields":[{"name":"Name","type":"Text","description":"Identifier for this adjustment record"},{"name":"BenefitAssignmentId","type":"Lookup","description":"Reference to the benefit assignment being adjusted"},{"name":"AdjustmentReason","type":"Picklist","description":"Reason for the adjustment such as Income Change, Household Change, or Recertification"},{"name":"NewAmount","type":"Currency","description":"Revised benefit amount after the adjustment"},{"name":"EffectiveDate","type":"Date","description":"Date when the adjustment takes effect"}],"relationships":[{"target":"BenefitAssignment","type":"lookup","description":"Links to the benefit assignment being modified"}]},
      {"name":"BenefitDisbursement","type":"standard","domain":"benefit_management","description":"Tracks a monetary payment or delivered quantity against a Benefit Assignment. Name, BenefitAssignmentId, Amount, DisbursementDate, Status, and DisbursedQuantity support payment processing and provider service-delivery tracking.","fields":[{"name":"Name","type":"Text","description":"Identifier for this disbursement record"},{"name":"BenefitAssignmentId","type":"Lookup","description":"Reference to the benefit assignment this disbursement fulfills"},{"name":"Amount","type":"Currency","description":"Monetary amount disbursed in this payment"},{"name":"DisbursementDate","type":"Date","description":"Date when the disbursement was made"},{"name":"Status","type":"Picklist","description":"Disbursement status: Pending, Completed, Failed, or Cancelled"},{"name":"DisbursedQuantity","type":"Number","description":"Quantity of service units delivered for session-based benefits"}],"relationships":[{"target":"BenefitAssignment","type":"lookup","description":"Links to the benefit assignment this disbursement is for"},{"target":"BenefitSession","type":"lookup","description":"Links to the session record for provider-delivered benefits"}]},
      {"name":"BenefitDisbursementAdj","type":"standard","domain":"benefit_management","description":"Records an adjustment associated with an existing Benefit Disbursement. Name, BenefitDisbursementId, AdjustmentAmount, AdjustmentReason, and EffectiveDate identify the affected disbursement, the value of the change, its reason, and its effective date.","fields":[{"name":"Name","type":"Text","description":"Identifier for the disbursement adjustment"},{"name":"BenefitDisbursementId","type":"Lookup","description":"Reference to the original disbursement being adjusted"},{"name":"AdjustmentAmount","type":"Currency","description":"Amount of the adjustment, positive for supplements or negative for clawbacks"},{"name":"AdjustmentReason","type":"Picklist","description":"Reason for the adjustment such as Overpayment, Underpayment, or Correction"},{"name":"EffectiveDate","type":"Date","description":"Date when the disbursement adjustment takes effect"}],"relationships":[{"target":"BenefitDisbursement","type":"lookup","description":"Links to the original disbursement record being adjusted"}]},
      {"name":"BenefitSchedule","type":"standard","domain":"benefit_management","description":"Defines the timing and recurrence of an assigned benefit or provider-delivered service. Name, BenefitAssignmentId, Frequency, SessionQuantity, StartDate, EndDate, and Status connect the schedule to an assignment and describe its active period and planned quantity.","fields":[{"name":"Name","type":"Text","description":"Name identifying this benefit schedule"},{"name":"BenefitAssignmentId","type":"Lookup","description":"Reference to the benefit assignment this schedule delivers"},{"name":"Frequency","type":"Picklist","description":"How often sessions occur: Daily, Weekly, Bi-Weekly, or Monthly"},{"name":"SessionQuantity","type":"Number","description":"Total number of sessions in this schedule"},{"name":"StartDate","type":"Date","description":"Start date for the schedule"},{"name":"EndDate","type":"Date","description":"End date for the schedule"},{"name":"Status","type":"Picklist","description":"Schedule status: Draft, Submitted, Approved, or Rejected"}],"relationships":[{"target":"BenefitAssignment","type":"lookup","description":"Links to the benefit assignment this schedule fulfills"},{"target":"BenefitSession","type":"parent","description":"Contains individual session records generated from this schedule"}]},
      {"name":"BenefitScheduleAssignment","type":"standard","domain":"benefit_management","description":"Associates a Benefit Schedule with a Benefit Assignment and tracks the relationship’s status. Name, BenefitScheduleId, BenefitAssignmentId, and Status identify the linked schedule and assignment.","fields":[{"name":"Name","type":"Text","description":"Name identifying this schedule assignment"},{"name":"BenefitScheduleId","type":"Lookup","description":"Reference to the benefit schedule being assigned"},{"name":"BenefitAssignmentId","type":"Lookup","description":"Reference to the benefit assignment this schedule serves"},{"name":"Status","type":"Picklist","description":"Assignment status: Active, Paused, or Completed"}],"relationships":[{"target":"BenefitSchedule","type":"lookup","description":"Links to the benefit schedule"},{"target":"BenefitAssignment","type":"lookup","description":"Links to the benefit assignment receiving this schedule"}]},
      {"name":"BenefitItemCode","type":"standard","domain":"benefit_management","description":"Maps a Benefit to a Code Set or Code Set Bundle that represents a distinct service or benefit variation. Name, BenefitId, CodesetId, CodesetBundleId, and Status identify the mapping and whether it is available for use.","fields":[{"name":"Name","type":"Text","description":"Name identifying this benefit item code"},{"name":"BenefitId","type":"Lookup","description":"Reference to the benefit this code maps to"},{"name":"CodesetId","type":"Lookup","description":"Reference to the code set representing the service variation"},{"name":"CodesetBundleId","type":"Lookup","description":"Reference to the code set bundle if multiple codes are grouped"},{"name":"Status","type":"Picklist","description":"Whether this item code is Active or Inactive"}],"relationships":[{"target":"Benefit","type":"lookup","description":"Links to the benefit this code categorizes"},{"target":"Codeset","type":"lookup","description":"Links to the code set representing the service variation"}]}
    ]
  },

  "social_insurance": {
    "objects": [
      {"name":"Claim","type":"standard","domain":"social_insurance","description":"Claim stores social insurance claim details, including the claimant account, claim type, status, filed date, approval status, and associated insurance policy. In the File a Claim flow, the Claim is created with a related Individual Application, while assessment responses and the generated PDF are related to the Individual Application.","fields":[{"name":"Name","type":"Text","description":"Claim identifier or reference number"},{"name":"AccountId","type":"Lookup","description":"Reference to the claimant's person account"},{"name":"ClaimType","type":"Picklist","description":"Type of insurance claim such as Workers Compensation, Disability, or Retirement"},{"name":"Status","type":"Picklist","description":"Claim status: Filed, Under Review, Approved, Denied, or Closed"},{"name":"FiledDate","type":"DateTime","description":"Date and time when the claim was filed"},{"name":"ApprovalStatus","type":"Picklist","description":"Approval disposition: Pending, Approved, or Denied"},{"name":"InsurancePolicyId","type":"Lookup","description":"Reference to the insurance policy under which this claim is filed"}],"relationships":[{"target":"Account","type":"lookup","description":"Links to the claimant's person account"},{"target":"InsurancePolicy","type":"lookup","description":"Links to the insurance policy associated with the claim"},{"target":"ClaimItem","type":"parent","description":"Contains line items detailing specific claim elements"},{"target":"ClaimParticipant","type":"parent","description":"Contains participants related to this claim"}]},
      {"name":"ClaimItem","type":"standard","domain":"social_insurance","description":"ClaimItem captures an item associated with a social insurance claim. Its fields identify the parent claim, amount, item category, and processing status.","fields":[{"name":"Name","type":"Text","description":"Description of the claim item such as Medical Treatment or Lost Wages"},{"name":"ClaimId","type":"Lookup","description":"Reference to the parent claim this item belongs to"},{"name":"Amount","type":"Currency","description":"Monetary amount for this claim item"},{"name":"ItemCategory","type":"Picklist","description":"Category such as Medical, Rehabilitation, Lost Wages, or Other"},{"name":"Status","type":"Picklist","description":"Item status: Submitted, Under Review, Approved, or Denied"}],"relationships":[{"target":"Claim","type":"lookup","description":"Links to the parent claim this item is part of"}]},
      {"name":"ClaimParticipant","type":"standard","domain":"social_insurance","description":"ClaimParticipant relates a constituent account to a social insurance claim and records the participant’s role and status. The documented File a Claim and Respond to Claim integrations create Individual Applications and claims or claim relationships, but do not state that they automatically create ClaimParticipant records.","fields":[{"name":"Name","type":"Text","description":"Name identifying this claim participant"},{"name":"ClaimId","type":"Lookup","description":"Reference to the claim this participant is related to"},{"name":"AccountId","type":"Lookup","description":"Reference to the participant's account"},{"name":"Role","type":"Picklist","description":"Role in the claim such as Claimant, Employer, Medical Provider, or Witness"},{"name":"Status","type":"Picklist","description":"Participation status: Active or Inactive"}],"relationships":[{"target":"Claim","type":"lookup","description":"Links to the claim this participant is involved in"},{"target":"Account","type":"lookup","description":"Links to the participant's account record"}]},
      {"name":"Codeset","type":"standard","domain":"social_insurance","description":"Codeset stores a diagnostic or service code with its description, code system, and status. In Social Insurance, code sets represent covered injury types and diagnostic codes that can be mapped to care barrier types for medical conditions.","fields":[{"name":"Name","type":"Text","description":"Name of the code set such as ICD-10 Diagnosis Code or Service Category Code"},{"name":"Code","type":"Text","description":"The diagnostic or service code value"},{"name":"Description","type":"LongTextArea","description":"Description of what this code represents"},{"name":"CodeSystem","type":"Picklist","description":"Classification system such as ICD-10, CPT, or Custom"},{"name":"Status","type":"Picklist","description":"Whether this code set is Active or Inactive"}],"relationships":[{"target":"CodesetBundle","type":"lookup","description":"Links to the code set bundle that groups this code with related codes"},{"target":"BenefitItemCode","type":"child","description":"Maps this code set to specific benefits for service variation tracking"}]},
      {"name":"CodesetBundle","type":"standard","domain":"social_insurance","description":"CodesetBundle groups related code sets for use in Public Sector Solutions processes. Its fields capture the bundle name, description, status, and bundle type.","fields":[{"name":"Name","type":"Text","description":"Name of the code set bundle such as Nursing Care Bundle or Physical Therapy Bundle"},{"name":"Description","type":"LongTextArea","description":"Description of the code sets grouped in this bundle and their purpose"},{"name":"Status","type":"Picklist","description":"Whether this bundle is Active or Inactive"},{"name":"BundleType","type":"Picklist","description":"Classification of the bundle such as Diagnostic, Service, or Treatment"}],"relationships":[{"target":"Codeset","type":"parent","description":"Contains the individual code sets grouped within this bundle"}]}
    ]
  },

  "provider_management": {
    "objects": [
      {"name":"HealthcareProvider","type":"standard","domain":"provider_management","description":"HealthcareProvider stores a provider’s name, provider type, status, associated account, and credential details. CredentialNumber and CredentialExpirationDate support capturing professional credential information for providers in the network.","fields":[{"name":"Name","type":"Text","description":"Display name of the healthcare provider such as City Counseling Center or Dr. Smith Physical Therapy"},{"name":"ProviderType","type":"Picklist","description":"Type of provider such as Individual Practitioner, Group Practice, or Organization"},{"name":"Status","type":"Picklist","description":"Verification status: Pending, Certified, Suspended, or Decertified"},{"name":"AccountId","type":"Lookup","description":"Reference to the provider's business account in Salesforce"},{"name":"CredentialNumber","type":"Text","description":"Professional credential or license number of the provider"},{"name":"CredentialExpirationDate","type":"Date","description":"Expiration date for the provider's credential or certification"}],"relationships":[{"target":"Account","type":"lookup","description":"Links to the provider's business account"},{"target":"HealthcareProviderSpecialty","type":"parent","description":"Contains specialty records defining this provider's areas of expertise"},{"target":"HealthcarePractitionerFacility","type":"parent","description":"Tracks which facilities this provider practices at"}]},
      {"name":"HealthcareFacility","type":"standard","domain":"provider_management","description":"HealthcareFacility represents a facility associated with provider service delivery, including its name, facility type, status, address, and location. Facility records participate in Provider Search and can be associated with provider specialties and benefit assignments.","fields":[{"name":"Name","type":"Text","description":"Name of the facility such as Downtown Rehabilitation Center or Northside Counseling Clinic"},{"name":"FacilityType","type":"Picklist","description":"Category of facility such as Clinic, Hospital, Rehabilitation Center, or Training Center"},{"name":"Status","type":"Picklist","description":"Certification status: Active, Pending Inspection, or Decertified"},{"name":"Address","type":"Text","description":"Street address of the facility"},{"name":"LocationId","type":"Lookup","description":"Reference to the Salesforce Location record for geolocation"}],"relationships":[{"target":"Location","type":"lookup","description":"Links to the geographic location record for distance-based provider search"},{"target":"HealthcarePractitionerFacility","type":"parent","description":"Contains records linking practitioners to this facility"},{"target":"CareProviderFacilitySpecialty","type":"parent","description":"Tracks which specialties are offered at this facility"}]},
      {"name":"HealthcarePractitionerFacility","type":"standard","domain":"provider_management","description":"HealthcarePractitionerFacility associates a HealthcareProvider with a HealthcareFacility. StartDate and EndDate define the period represented by the association, and duplicate associations for the same provider and facility can cause failed Data Processing Engine writebacks.","fields":[{"name":"Name","type":"Text","description":"Name identifying this practitioner-facility association"},{"name":"HealthcareProviderId","type":"Lookup","description":"Reference to the healthcare provider (practitioner)"},{"name":"HealthcareFacilityId","type":"Lookup","description":"Reference to the facility where the practitioner works"},{"name":"StartDate","type":"Date","description":"Date when the practitioner began working at this facility"},{"name":"EndDate","type":"Date","description":"Date when the practitioner stopped working at this facility, if applicable"}],"relationships":[{"target":"HealthcareProvider","type":"lookup","description":"Links to the practitioner provider record"},{"target":"HealthcareFacility","type":"lookup","description":"Links to the facility where services are delivered"}]},
      {"name":"CareSpecialty","type":"standard","domain":"provider_management","description":"CareSpecialty represents a specialty that can be offered by providers or facilities and mapped to agency benefits. It stores the specialty name, description, category, and status used to manage that specialty.","fields":[{"name":"Name","type":"Text","description":"Name of the care specialty such as Grief Counseling or Physical Therapy"},{"name":"Description","type":"LongTextArea","description":"Description of the specialty and the types of services it covers"},{"name":"SpecialtyCategory","type":"Picklist","description":"Broad category such as Mental Health, Physical Rehabilitation, or Vocational Training"},{"name":"Status","type":"Picklist","description":"Whether this specialty is actively available in the provider network"}],"relationships":[{"target":"HealthcareProviderSpecialty","type":"child","description":"Provider records linked to this specialty"},{"target":"CareProviderFacilitySpecialty","type":"child","description":"Facility records offering this specialty"}]},
      {"name":"CareProviderFacilitySpecialty","type":"standard","domain":"provider_management","description":"CareProviderFacilitySpecialty associates a HealthcareFacility with a CareSpecialty and records the association’s status. Provider Search uses facility-specialty information when compiling searchable provider data.","fields":[{"name":"Name","type":"Text","description":"Name identifying this facility-specialty link"},{"name":"HealthcareFacilityId","type":"Lookup","description":"Reference to the facility offering this specialty"},{"name":"CareSpecialtyId","type":"Lookup","description":"Reference to the care specialty available at this facility"},{"name":"Status","type":"Picklist","description":"Whether this specialty is currently offered at the facility"}],"relationships":[{"target":"HealthcareFacility","type":"lookup","description":"Links to the facility where this specialty is offered"},{"target":"CareSpecialty","type":"lookup","description":"Links to the specialty offered at this facility"}]},
      {"name":"HealthcareProviderSpecialty","type":"standard","domain":"provider_management","description":"HealthcareProviderSpecialty associates a HealthcareProvider with a CareSpecialty and tracks the association’s status. Duplicate records for the same provider and specialty can cause failed writeback records when the Provider Search Data Processing Engine definition runs.","fields":[{"name":"Name","type":"Text","description":"Name identifying this provider-specialty association"},{"name":"HealthcareProviderId","type":"Lookup","description":"Reference to the healthcare provider"},{"name":"CareSpecialtyId","type":"Lookup","description":"Reference to the care specialty the provider is qualified in"},{"name":"Status","type":"Picklist","description":"Whether this specialty is actively offered by the provider"}],"relationships":[{"target":"HealthcareProvider","type":"lookup","description":"Links to the provider with this specialty"},{"target":"CareSpecialty","type":"lookup","description":"Links to the care specialty the provider offers"}]},
      {"name":"BenefitSpecialty","type":"standard","domain":"provider_management","description":"BenefitSpecialty maps a Benefit to a CareSpecialty and records the mapping’s status. This mapping enables Provider Search to find providers and facilities whose specialties can deliver the benefit.","fields":[{"name":"Name","type":"Text","description":"Name identifying this benefit-to-specialty mapping"},{"name":"BenefitId","type":"Lookup","description":"Reference to the agency benefit"},{"name":"CareSpecialtyId","type":"Lookup","description":"Reference to the provider specialty that can deliver this benefit"},{"name":"Status","type":"Picklist","description":"Whether this mapping is currently active"}],"relationships":[{"target":"Benefit","type":"lookup","description":"Links to the agency benefit that requires this provider specialty"},{"target":"CareSpecialty","type":"lookup","description":"Links to the specialty needed to deliver the benefit"}]},
      {"name":"BenefitAsgntProviderLoc","type":"standard","domain":"provider_management","description":"BenefitAsgntProviderLoc associates a BenefitAssignment with a HealthcareFacility and HealthcareProvider and tracks the association’s status. The record identifies the provider and facility connected to an assigned benefit.","fields":[{"name":"Name","type":"Text","description":"Name identifying this assignment-provider-location link"},{"name":"BenefitAssignmentId","type":"Lookup","description":"Reference to the benefit assignment being served"},{"name":"HealthcareFacilityId","type":"Lookup","description":"Reference to the provider facility where services are delivered"},{"name":"HealthcareProviderId","type":"Lookup","description":"Reference to the provider delivering the service"},{"name":"Status","type":"Picklist","description":"Status of the provider-location assignment: Active, Completed, or Transferred"}],"relationships":[{"target":"BenefitAssignment","type":"lookup","description":"Links to the benefit assignment being fulfilled at this location"},{"target":"HealthcareFacility","type":"lookup","description":"Links to the facility where the benefit is being delivered"},{"target":"HealthcareProvider","type":"lookup","description":"Links to the provider delivering the benefit"}]},
      {"name":"BenefitPrvdSearchableFld","type":"standard","domain":"provider_management","description":"BenefitPrvdSearchableFld is the searchable object that Data Processing Engine populates from multiple Provider Management source objects. Its provider, facility, specialty, address, and distance information supports Criteria-Based Search and Filter provider searches.","fields":[{"name":"Name","type":"Text","description":"Auto-generated name for the searchable record"},{"name":"ProviderName","type":"Text","description":"Name of the provider for display in search results"},{"name":"FacilityName","type":"Text","description":"Name of the facility for display in search results"},{"name":"SpecialtyName","type":"Text","description":"Name of the provider's specialty"},{"name":"Address","type":"Text","description":"Facility address for distance-based search filtering"},{"name":"Distance","type":"Number","description":"Calculated distance from search origin for proximity filtering"}],"relationships":[{"target":"HealthcareProvider","type":"lookup","description":"Links back to the source provider record"},{"target":"HealthcareFacility","type":"lookup","description":"Links back to the source facility record"}]},
      {"name":"BenefitSession","type":"standard","domain":"provider_management","description":"BenefitSession represents an occurrence in an approved BenefitSchedule, including its session date, status, attendance status, and quantity. Providers enroll constituents in sessions and record attendance, while related benefit disbursements track delivery of the assigned benefit.","fields":[{"name":"Name","type":"Text","description":"Name identifying this session"},{"name":"BenefitScheduleId","type":"Lookup","description":"Reference to the benefit schedule this session belongs to"},{"name":"SessionDate","type":"DateTime","description":"Date and time when the session is scheduled"},{"name":"Status","type":"Picklist","description":"Session status: Scheduled, Completed, Cancelled, or No-Show"},{"name":"AttendanceStatus","type":"Picklist","description":"Constituent attendance status: Present, Absent, or Excused"},{"name":"Quantity","type":"Number","description":"Quantity of service units delivered in this session"}],"relationships":[{"target":"BenefitSchedule","type":"lookup","description":"Links to the benefit schedule containing this session"},{"target":"BenefitDisbursement","type":"child","description":"Disbursement record created when a constituent is enrolled in this session"}]}
    ]
  },

  "investigative_cases": {
    "objects": [
      {"name":"ComplaintCase","type":"standard","domain":"investigative_cases","description":"ComplaintCase links a public complaint to an investigative case and records the relationship's screening result and status. Its Name, PublicComplaintId, CaseId, ScreeningResult, and Status fields support linking multiple complaints to one case, and Field Audit Trail is enabled for this object.","fields":[{"name":"Name","type":"Text","description":"Identifier for the complaint case link"},{"name":"PublicComplaintId","type":"Lookup","description":"Reference to the original public complaint"},{"name":"CaseId","type":"Lookup","description":"Reference to the investigative case created from the complaint"},{"name":"ScreeningResult","type":"Picklist","description":"Result of the complaint screening: Substantiated, Unsubstantiated, or Pending"},{"name":"Status","type":"Picklist","description":"Status of the complaint-to-case link: Active, Closed, or Transferred"}],"relationships":[{"target":"PublicComplaint","type":"lookup","description":"Links to the original public complaint that was screened"},{"target":"Case","type":"lookup","description":"Links to the investigative case created from the complaint"}]},
      {"name":"ComplaintParticipant","type":"standard","domain":"investigative_cases","description":"ComplaintParticipant records an account associated with a public complaint, including the participant's role and status. Its Name, PublicComplaintId, AccountId, Role, and Status fields support party association and compliant data-sharing scenarios, and Field Audit Trail is enabled for this object.","fields":[{"name":"Name","type":"Text","description":"Name identifying this complaint participant"},{"name":"PublicComplaintId","type":"Lookup","description":"Reference to the complaint this participant is associated with"},{"name":"AccountId","type":"Lookup","description":"Reference to the participant's account record"},{"name":"Role","type":"Picklist","description":"Role in the complaint: Complainant, Respondent, Witness, or Alleged Victim"},{"name":"Status","type":"Picklist","description":"Participation status: Active or Inactive"}],"relationships":[{"target":"PublicComplaint","type":"lookup","description":"Links to the complaint this participant is involved in"},{"target":"Account","type":"lookup","description":"Links to the participant's account"}]},
      {"name":"CaseProceeding","type":"standard","domain":"investigative_cases","description":"CaseProceeding stores a legal proceeding associated with a case, including its type, status, scheduled date, and venue. Its Name, CaseId, ProceedingType, Status, ScheduledDate, and Venue fields provide the core proceeding record, and Field Audit Trail is enabled for this object.","fields":[{"name":"Name","type":"Text","description":"Name or docket number of the case proceeding"},{"name":"CaseId","type":"Lookup","description":"Reference to the investigative case this proceeding belongs to"},{"name":"ProceedingType","type":"Picklist","description":"Type of proceeding: Court Action, Appeal, Mediation, Arbitration, or Hearing"},{"name":"Status","type":"Picklist","description":"Current status: Scheduled, In Progress, Completed, Dismissed, or Adjourned"},{"name":"ScheduledDate","type":"DateTime","description":"Scheduled date and time for the proceeding"},{"name":"Venue","type":"Text","description":"Court or venue where the proceeding takes place"}],"relationships":[{"target":"Case","type":"lookup","description":"Links to the investigative case associated with this proceeding"},{"target":"CaseProceedingResult","type":"parent","description":"Contains the results or outcomes of this proceeding"},{"target":"CaseProceedingInfraction","type":"parent","description":"Contains infractions linked to regulatory code violations"}]},
      {"name":"CaseProceedingComplaint","type":"standard","domain":"investigative_cases","description":"CaseProceedingComplaint relates a public complaint to a case proceeding and tracks the relationship status. Its Name, CaseProceedingId, PublicComplaintId, and Status fields support the association, and Field Audit Trail is enabled for this object.","fields":[{"name":"Name","type":"Text","description":"Name identifying this proceeding-complaint link"},{"name":"CaseProceedingId","type":"Lookup","description":"Reference to the case proceeding"},{"name":"PublicComplaintId","type":"Lookup","description":"Reference to the public complaint linked to this proceeding"},{"name":"Status","type":"Picklist","description":"Status of the link: Active or Resolved"}],"relationships":[{"target":"CaseProceeding","type":"lookup","description":"Links to the case proceeding"},{"target":"PublicComplaint","type":"lookup","description":"Links to the original complaint"}]},
      {"name":"CaseProceedingInfraction","type":"standard","domain":"investigative_cases","description":"CaseProceedingInfraction associates a RegulatoryCodeViolation with a case proceeding and records its severity and status. Its Name, CaseProceedingId, RegulatoryCodeViolationId, Severity, and Status fields capture the proceeding-level infraction, and Field Audit Trail is enabled for this object.","fields":[{"name":"Name","type":"Text","description":"Name identifying this infraction record"},{"name":"CaseProceedingId","type":"Lookup","description":"Reference to the case proceeding where this infraction is addressed"},{"name":"RegulatoryCodeViolationId","type":"Lookup","description":"Reference to the regulatory code violation constituting this infraction"},{"name":"Severity","type":"Picklist","description":"Severity classification of the infraction"},{"name":"Status","type":"Picklist","description":"Current status: Open, Adjudicated, or Dismissed"}],"relationships":[{"target":"CaseProceeding","type":"lookup","description":"Links to the proceeding addressing this infraction"},{"target":"RegulatoryCodeViolation","type":"lookup","description":"Links to the regulatory code violation that constitutes this infraction"}]},
      {"name":"CaseProceedingParticipant","type":"standard","domain":"investigative_cases","description":"CaseProceedingParticipant records an account participating in a case proceeding, together with the assigned role and status. Its Name, CaseProceedingId, AccountId, Role, and Status fields support proceeding participation, and Field Audit Trail is enabled for this object.","fields":[{"name":"Name","type":"Text","description":"Name identifying this proceeding participant"},{"name":"CaseProceedingId","type":"Lookup","description":"Reference to the case proceeding"},{"name":"AccountId","type":"Lookup","description":"Reference to the participant's account"},{"name":"Role","type":"Picklist","description":"Role in the proceeding: Defendant, Plaintiff, Prosecutor, Defense Counsel, Judge, or Witness"},{"name":"Status","type":"Picklist","description":"Participation status: Active, Excused, or Withdrawn"}],"relationships":[{"target":"CaseProceeding","type":"lookup","description":"Links to the case proceeding this participant is involved in"},{"target":"Account","type":"lookup","description":"Links to the participant's account record"}]},
      {"name":"CaseProceedingResult","type":"standard","domain":"investigative_cases","description":"CaseProceedingResult records the disposition and result date of a legal proceeding, with descriptive details about the decision or ruling. Its Name, CaseProceedingId, Disposition, ResultDate, and Description fields capture the outcome, and Field Audit Trail is enabled for this object.","fields":[{"name":"Name","type":"Text","description":"Name identifying this proceeding result"},{"name":"CaseProceedingId","type":"Lookup","description":"Reference to the case proceeding this result belongs to"},{"name":"Disposition","type":"Picklist","description":"Outcome such as Guilty, Not Guilty, Dismissed, Settled, or Continued"},{"name":"ResultDate","type":"Date","description":"Date when the result was rendered"},{"name":"Description","type":"LongTextArea","description":"Detailed description of the ruling, penalties, or remediation orders"}],"relationships":[{"target":"CaseProceeding","type":"lookup","description":"Links to the case proceeding that produced this result"}]},
      {"name":"CaseParticipant","type":"standard","domain":"investigative_cases","description":"CaseParticipant identifies an account involved in an investigative case and records the participant's role and status. Its Name, CaseId, AccountId, Role, and Status fields support participant views and ARC relationship graphs, and Field Audit Trail is enabled for this object.","fields":[{"name":"Name","type":"Text","description":"Name identifying this case participant"},{"name":"CaseId","type":"Lookup","description":"Reference to the investigative case"},{"name":"AccountId","type":"Lookup","description":"Reference to the participant's account"},{"name":"Role","type":"Picklist","description":"Role in the case: Victim, Suspect, Witness, Investigator, or Caseworker"},{"name":"Status","type":"Picklist","description":"Participation status: Active, Inactive, or Protected"}],"relationships":[{"target":"Case","type":"lookup","description":"Links to the investigative case this participant is involved in"},{"target":"Account","type":"lookup","description":"Links to the participant's account record"}]},
      {"name":"CaseEpisode","type":"standard","domain":"investigative_cases","description":"CaseEpisode represents an event related to legal proceedings, such as detention, license suspension, or temporary foster-care placement. Its Name, CaseId, EpisodeType, Status, StartDate, and EndDate fields track the event and its duration, and Field Audit Trail is enabled for this object.","fields":[{"name":"Name","type":"Text","description":"Name of the case episode such as Initial Investigation or Prosecution Phase"},{"name":"CaseId","type":"Lookup","description":"Reference to the investigative case this episode belongs to"},{"name":"EpisodeType","type":"Picklist","description":"Type of episode: Investigation, Evidence Collection, Prosecution, or Resolution"},{"name":"Status","type":"Picklist","description":"Episode status: Active, Completed, or On Hold"},{"name":"StartDate","type":"Date","description":"Date when this episode began"},{"name":"EndDate","type":"Date","description":"Date when this episode ended"}],"relationships":[{"target":"Case","type":"lookup","description":"Links to the investigative case this episode is part of"}]},
      {"name":"CustodyItem","type":"standard","domain":"investigative_cases","description":"CustodyItem represents physical or digital evidence managed for an investigative case or case proceeding. Its Name, Description, Status, CustodySite, VerificationType, and CollectedDate fields record identifying, collection, custody-site, and verification information for the item.","fields":[{"name":"Name","type":"Text","description":"Name or description of the custody item such as Surveillance Video or Physical Evidence Sample"},{"name":"Description","type":"LongTextArea","description":"Detailed description of the evidence item"},{"name":"Status","type":"Picklist","description":"Current status: In Custody, Released, Disposed, or Transferred"},{"name":"CustodySite","type":"Text","description":"Location where the evidence is stored or maintained"},{"name":"VerificationType","type":"Picklist","description":"Method used to verify the evidence: Visual, Forensic, Digital, or Testimonial"},{"name":"CollectedDate","type":"DateTime","description":"Date and time when the evidence was collected"}],"relationships":[{"target":"CustodyChainEntry","type":"parent","description":"Contains chain of custody entries tracking evidence transfers"},{"target":"CustodyItemRelation","type":"parent","description":"Links this evidence to investigative cases"},{"target":"CustodyItemRgltyCodeVio","type":"parent","description":"Links this evidence to regulatory code violations"}]},
      {"name":"CustodyChainEntry","type":"standard","domain":"investigative_cases","description":"CustodyChainEntry records a custody event for a custody item, including the custodian, transfer date, reason, and location. Its Name, CustodyItemId, CustodianId, TransferDate, TransferReason, and Location fields support chronological tracking of possession; Field Audit Trail is not documented as enabled for this object.","fields":[{"name":"Name","type":"Text","description":"Name identifying this chain of custody entry"},{"name":"CustodyItemId","type":"Lookup","description":"Reference to the custody item being transferred"},{"name":"CustodianId","type":"Lookup","description":"Reference to the user or contact receiving custody"},{"name":"TransferDate","type":"DateTime","description":"Date and time when the custody transfer occurred"},{"name":"TransferReason","type":"Text","description":"Reason for the custody transfer such as Lab Analysis or Court Presentation"},{"name":"Location","type":"Text","description":"Physical location where the item is stored after transfer"}],"relationships":[{"target":"CustodyItem","type":"lookup","description":"Links to the custody item being tracked through this chain entry"}]},
      {"name":"CustodyItemRelation","type":"standard","domain":"investigative_cases","description":"CustodyItemRelation connects a custody item to a case and records the relationship type and status. Its Name, CustodyItemId, CaseId, RelationType, and Status fields establish the evidence-to-case association, and Field Audit Trail is enabled for this object.","fields":[{"name":"Name","type":"Text","description":"Name identifying this custody item to case link"},{"name":"CustodyItemId","type":"Lookup","description":"Reference to the custody item (evidence)"},{"name":"CaseId","type":"Lookup","description":"Reference to the investigative case"},{"name":"RelationType","type":"Picklist","description":"Type of relationship such as Primary Evidence, Supporting Evidence, or Reference"},{"name":"Status","type":"Picklist","description":"Status of the evidence-case link: Active, Superseded, or Removed"}],"relationships":[{"target":"CustodyItem","type":"lookup","description":"Links to the evidence item"},{"target":"Case","type":"lookup","description":"Links to the investigative case"}]},
      {"name":"CustodyItemRgltyCodeVio","type":"standard","domain":"investigative_cases","description":"CustodyItemRgltyCodeVio links a custody item to a RegulatoryCodeViolation and records the relationship status. Its Name, CustodyItemId, RegulatoryCodeViolationId, and Status fields associate evidence with a violation, and Field Audit Trail is enabled for this object.","fields":[{"name":"Name","type":"Text","description":"Name identifying this evidence-to-violation link"},{"name":"CustodyItemId","type":"Lookup","description":"Reference to the custody item (evidence)"},{"name":"RegulatoryCodeViolationId","type":"Lookup","description":"Reference to the regulatory code violation this evidence relates to"},{"name":"Status","type":"Picklist","description":"Status of the link: Active or Superseded"}],"relationships":[{"target":"CustodyItem","type":"lookup","description":"Links to the evidence item"},{"target":"RegulatoryCodeViolation","type":"lookup","description":"Links to the regulatory code violation"}]}
    ]
  },

  "talent_recruitment": {
    "objects": [
      {"name":"JobPosition","type":"standard","domain":"talent_recruitment","description":"Represents a specific instance of a Position in the organization, including a position that is vacant or held by an employee. Name, PositionId, Status, DepartmentName, EmployeeId, and StartDate identify its classification, organizational placement, assignment, and effective start.","fields":[{"name":"Name","type":"Text","description":"Display name identifying the job position such as Financial Auditor in Public Welfare"},{"name":"PositionId","type":"Lookup","description":"Reference to the position classification that defines the functional role"},{"name":"Status","type":"Picklist","description":"Current status of the job position such as Vacant, Filled, or Abolished"},{"name":"DepartmentName","type":"Text","description":"Name of the department or organizational unit where this job position exists"},{"name":"EmployeeId","type":"Lookup","description":"Reference to the employee currently holding this job position"},{"name":"StartDate","type":"Date","description":"Date when this job position became active or was created"}],"relationships":[{"target":"Position","type":"lookup","description":"Links to the position classification defining the functional role and qualifications"},{"target":"JobPositionPayGrade","type":"parent","description":"Parent of pay grade assignments that define compensation for this job position"},{"target":"JobPstnRecruitmentRqs","type":"parent","description":"Parent of junction records linking this job position to recruitment requisitions"}]},
      {"name":"JobPositionPayGrade","type":"standard","domain":"talent_recruitment","description":"Associates a JobPosition with an applicable PayGrade. Name, JobPositionId, and PayGradeId identify the individual job position and compensation grade being matched.","fields":[{"name":"Name","type":"AutoNumber","description":"Auto-generated identifier for the job position pay grade assignment"},{"name":"JobPositionId","type":"Lookup","description":"Reference to the job position being assigned a pay grade"},{"name":"PayGradeId","type":"Lookup","description":"Reference to the pay grade assigned to this job position"}],"relationships":[{"target":"JobPosition","type":"lookup","description":"Links to the specific job position being compensated"},{"target":"PayGrade","type":"lookup","description":"Links to the pay grade defining the salary range"}]},
      {"name":"Position","type":"standard","domain":"talent_recruitment","description":"Represents a functional role within an Occupation with defined duties, responsibilities, and work characteristics. Name, OccupationId, ScheduleType, and Description capture the position’s classification and descriptive details.","fields":[{"name":"Name","type":"Text","description":"Display name of the position such as Accountant or Performance Auditor"},{"name":"OccupationId","type":"Lookup","description":"Reference to the occupation classification this position belongs to"},{"name":"ScheduleType","type":"Picklist","description":"Work schedule classification such as Full-time or Part-time"},{"name":"Description","type":"LongTextArea","description":"Detailed description of duties, responsibilities, and requirements for this position"}],"relationships":[{"target":"Occupation","type":"lookup","description":"Links to the occupation category this position belongs to"},{"target":"PositionPayGrade","type":"parent","description":"Parent of pay grade assignments that define compensation ranges for this position"},{"target":"JobPosition","type":"parent","description":"Parent of concrete job position instances derived from this position"}]},
      {"name":"PositionPayGrade","type":"standard","domain":"talent_recruitment","description":"Associates a Position with a PayGrade so that positions with comparable responsibilities can use the appropriate pay band. Name, PositionId, and PayGradeId identify the linked position and grade.","fields":[{"name":"Name","type":"AutoNumber","description":"Auto-generated identifier for the position pay grade assignment"},{"name":"PositionId","type":"Lookup","description":"Reference to the position being assigned a pay grade"},{"name":"PayGradeId","type":"Lookup","description":"Reference to the pay grade assigned to this position"}],"relationships":[{"target":"Position","type":"lookup","description":"Links to the functional role being compensated"},{"target":"PayGrade","type":"lookup","description":"Links to the pay grade defining the salary band"}]},
      {"name":"PayGrade","type":"standard","domain":"talent_recruitment","description":"Represents a pay band or salary range for positions requiring similar responsibilities and competencies. Name, MinimumPay, MaximumPay, and Description define the grade and its compensation range.","fields":[{"name":"Name","type":"Text","description":"Display name of the pay grade such as GS-12 or Grade 7"},{"name":"MinimumPay","type":"Currency","description":"Minimum salary or hourly rate for this pay grade"},{"name":"MaximumPay","type":"Currency","description":"Maximum salary or hourly rate for this pay grade"},{"name":"Description","type":"LongTextArea","description":"Description of the pay grade including applicable positions and responsibilities"}],"relationships":[{"target":"PayGradeStep","type":"parent","description":"Parent of pay grade steps that define incremental increases within this band"},{"target":"PositionPayGrade","type":"parent","description":"Parent of junction records linking this grade to positions"}]},
      {"name":"PayGradeStep","type":"standard","domain":"talent_recruitment","description":"Represents a pay increase level within a PayGrade. Name, PayGradeId, StepAmount, and StepNumber identify the parent grade, sequence, and amount for the step.","fields":[{"name":"Name","type":"Text","description":"Display name of the pay grade step such as Step 5 or Step 10"},{"name":"PayGradeId","type":"Lookup","description":"Reference to the parent pay grade this step belongs to"},{"name":"StepAmount","type":"Currency","description":"The salary or hourly rate at this step level"},{"name":"StepNumber","type":"Number","description":"Ordinal number of this step within the pay grade"}],"relationships":[{"target":"PayGrade","type":"lookup","description":"Links to the parent pay grade this step belongs to"},{"target":"PayGradeStepLocation","type":"parent","description":"Parent of location-specific pay step adjustments"}]},
      {"name":"PayGradeStepLocation","type":"standard","domain":"talent_recruitment","description":"Represents a location-specific adjustment to a PayGradeStep. Name, PayGradeStepId, LocationName, and AdjustedAmount identify the step, applicable location, and adjusted compensation amount.","fields":[{"name":"Name","type":"Text","description":"Display name identifying the location-specific pay step"},{"name":"PayGradeStepId","type":"Lookup","description":"Reference to the parent pay grade step"},{"name":"LocationName","type":"Text","description":"Name of the geographic locality or region for this pay adjustment"},{"name":"AdjustedAmount","type":"Currency","description":"The locality-adjusted salary or hourly rate at this step"}],"relationships":[{"target":"PayGradeStep","type":"lookup","description":"Links to the pay grade step being adjusted for this location"}]},
      {"name":"Occupation","type":"standard","domain":"talent_recruitment","description":"Represents a specialized category of work requiring similar skills, knowledge, or qualifications. Name, OccupationGroupId, Status, and Description identify its parent group and describe its active classification.","fields":[{"name":"Name","type":"Text","description":"Name of the occupation such as Accounting or Budget Analysis"},{"name":"OccupationGroupId","type":"Lookup","description":"Reference to the parent occupation group"},{"name":"Status","type":"Picklist","description":"Whether this occupation is Active or Inactive"},{"name":"Description","type":"LongTextArea","description":"Description of the skills, knowledge, and qualifications required"}],"relationships":[{"target":"OccupationGroup","type":"lookup","description":"Links to the broader occupation group this category belongs to"},{"target":"Position","type":"parent","description":"Parent of positions that represent functional roles within this occupation"}]},
      {"name":"OccupationGroup","type":"standard","domain":"talent_recruitment","description":"Represents a broad category of related occupations that require similar functions, skills, or equipment. Name, Status, and Description define and describe the group.","fields":[{"name":"Name","type":"Text","description":"Name of the occupation group such as Professional and Administrative Occupations"},{"name":"Status","type":"Picklist","description":"Whether this occupation group is Active or Inactive"},{"name":"Description","type":"LongTextArea","description":"Description of the broad category including the types of occupations it encompasses"}],"relationships":[{"target":"Occupation","type":"parent","description":"Parent of occupation categories grouped under this classification"}]},
      {"name":"RecruitmentRequisition","type":"standard","domain":"talent_recruitment","description":"Represents a formal request to fill one or more specific job positions. Name, VacancyType, DefaultPostingLanguage, Status, and HiringManagerId capture the vacancy, posting defaults, workflow state, and responsible hiring manager.","fields":[{"name":"Name","type":"Text","description":"Display name or title of the recruitment requisition"},{"name":"VacancyType","type":"Picklist","description":"Type of vacancy such as Full-time or Part-time"},{"name":"DefaultPostingLanguage","type":"Picklist","description":"Default language for job postings such as English or Espanol"},{"name":"Status","type":"Picklist","description":"Approval and processing status of the requisition"},{"name":"HiringManagerId","type":"Lookup","description":"Reference to the hiring manager responsible for this requisition"}],"relationships":[{"target":"JobPstnRecruitmentRqs","type":"parent","description":"Parent of junction records linking this requisition to job positions"},{"target":"RecruitmentRequisitionLoc","type":"parent","description":"Parent of location records specifying where the vacancy exists"},{"target":"RecruitmentRequisitionPtcp","type":"parent","description":"Parent of participant records tracking hiring managers and interviewers"},{"target":"RecruitmentPosting","type":"parent","description":"Parent of job postings created from this requisition"}]},
      {"name":"RecruitmentRequisitionLoc","type":"standard","domain":"talent_recruitment","description":"Associates a RecruitmentRequisition with a hiring location. Name, RecruitmentRequisitionId, and LocationName identify the requisition and applicable location.","fields":[{"name":"Name","type":"AutoNumber","description":"Auto-generated identifier for the requisition location record"},{"name":"RecruitmentRequisitionId","type":"Lookup","description":"Reference to the parent recruitment requisition"},{"name":"LocationName","type":"Text","description":"Name or address of the location where the vacancy exists"}],"relationships":[{"target":"RecruitmentRequisition","type":"lookup","description":"Links to the parent requisition this location belongs to"}]},
      {"name":"RecruitmentRequisitionPtcp","type":"standard","domain":"talent_recruitment","description":"Associates a user participant with a RecruitmentRequisition and records the participant’s role. Name, RecruitmentRequisitionId, ParticipantRole, and UserId support collaboration and participant-based access for requisition workflows.","fields":[{"name":"Name","type":"AutoNumber","description":"Auto-generated identifier for the requisition participant"},{"name":"RecruitmentRequisitionId","type":"Lookup","description":"Reference to the recruitment requisition this participant is associated with"},{"name":"ParticipantRole","type":"Picklist","description":"Role of the participant such as Hiring Manager or Interviewer"},{"name":"UserId","type":"Lookup","description":"Reference to the Salesforce user participating in the requisition"}],"relationships":[{"target":"RecruitmentRequisition","type":"lookup","description":"Links to the requisition this participant is involved with"}]},
      {"name":"JobPstnRecruitmentRqs","type":"standard","domain":"talent_recruitment","description":"Associates a JobPosition with a RecruitmentRequisition for a vacancy being filled. Name, JobPositionId, and RecruitmentRequisitionId identify the linked job position and requisition.","fields":[{"name":"Name","type":"AutoNumber","description":"Auto-generated identifier for the junction record"},{"name":"JobPositionId","type":"Lookup","description":"Reference to the job position being recruited for"},{"name":"RecruitmentRequisitionId","type":"Lookup","description":"Reference to the recruitment requisition for this job position"}],"relationships":[{"target":"JobPosition","type":"lookup","description":"Links to the job position the requisition aims to fill"},{"target":"RecruitmentRequisition","type":"lookup","description":"Links to the recruitment requisition for this position"}]},
      {"name":"RecruitmentPosting","type":"standard","domain":"talent_recruitment","description":"Stores details of a job posting created for a RecruitmentRequisition. Name, RecruitmentRequisitionId, CandidateSourceKey, Status, PostingDate, and SearchableField capture its source, publication state, date, and search-related data.","fields":[{"name":"Name","type":"Text","description":"Title of the job posting as displayed to applicants"},{"name":"RecruitmentRequisitionId","type":"Lookup","description":"Reference to the approved requisition this posting is based on"},{"name":"CandidateSourceKey","type":"Picklist","description":"Where the posting is published such as Career Site or External Portal"},{"name":"Status","type":"Picklist","description":"Current status of the posting: Active, Draft, Inactive, or Waiting for Approval"},{"name":"PostingDate","type":"Date","description":"Date when this posting was published on the career site"},{"name":"SearchableField","type":"LongTextArea","description":"Compiled searchable content populated by the Data Processing Engine for career site search"}],"relationships":[{"target":"RecruitmentRequisition","type":"lookup","description":"Links to the approved requisition this posting advertises"},{"target":"RecruitmentPostingCntntSect","type":"parent","description":"Parent of content section records containing posting details"}]},
      {"name":"RecruitmentPostingCntntSect","type":"standard","domain":"talent_recruitment","description":"Associates a RecruitmentPosting with a RecruitmentContentSection included in the posting. Name, RecruitmentPostingId, and RecruitmentContentSectionId identify the linked posting and content section.","fields":[{"name":"Name","type":"AutoNumber","description":"Auto-generated identifier for the posting content section link"},{"name":"RecruitmentPostingId","type":"Lookup","description":"Reference to the parent recruitment posting"},{"name":"RecruitmentContentSectionId","type":"Lookup","description":"Reference to the reusable content section"}],"relationships":[{"target":"RecruitmentPosting","type":"lookup","description":"Links to the job posting this content section belongs to"},{"target":"RecruitmentContentSection","type":"lookup","description":"Links to the reusable content block"}]},
      {"name":"RecruitmentContentSection","type":"standard","domain":"talent_recruitment","description":"Stores reusable content for a recruitment posting section, such as Overview, Summary, or Duties. Name, Language, Status, Type, and Content define the section’s classification, lifecycle, language, and body content.","fields":[{"name":"Name","type":"Text","description":"Display name of the content section"},{"name":"Language","type":"Picklist","description":"Language of the content such as English or Espanol"},{"name":"Status","type":"Picklist","description":"Whether this content section is Active or Inactive"},{"name":"Type","type":"Picklist","description":"Category of content: Overview, Summary, or Duties"},{"name":"Content","type":"RichTextArea","description":"The actual content text displayed in the job posting"}],"relationships":[{"target":"RecruitmentPostingCntntSect","type":"parent","description":"Parent of junction records linking this section to job postings"}]},
      {"name":"ApplicationFormRelation","type":"standard","domain":"talent_recruitment","description":"Associates an Application Form with a related Recruitment Requisition in the job application process. Name, ApplicationFormId, RelatedRecordId, and Role identify the application, related requisition record, and relationship role; participant association is handled separately through Application Form Participants and Application Form Evaluation Participants.","fields":[{"name":"Name","type":"AutoNumber","description":"Auto-generated identifier for the application form relation"},{"name":"ApplicationFormId","type":"Lookup","description":"Reference to the application form this relation belongs to"},{"name":"RelatedRecordId","type":"Lookup","description":"Reference to the related record such as a person account or user"},{"name":"Role","type":"Picklist","description":"Role of the related party such as Applicant, Evaluator, or Collaborator"}],"relationships":[{"target":"ApplicationForm","type":"lookup","description":"Links to the parent application form"}]},
      {"name":"ApplicationFormEvalPtcp","type":"standard","domain":"talent_recruitment","description":"Associates a participant with an Application Form Evaluation and records the participant’s evaluation role. Name, ApplicationFormEvaluationId, ParticipantId, and Role support assignment and sharing of evaluations with hiring managers, interviewers, or other evaluators.","fields":[{"name":"Name","type":"AutoNumber","description":"Auto-generated identifier for the evaluation participant"},{"name":"ApplicationFormEvaluationId","type":"Lookup","description":"Reference to the application form evaluation this participant belongs to"},{"name":"ParticipantId","type":"Lookup","description":"Reference to the user or contact participating in the evaluation"},{"name":"Role","type":"Picklist","description":"Role of the participant such as Hiring Manager or Interviewer"}],"relationships":[{"target":"ApplicationFormEvaluation","type":"lookup","description":"Links to the application form evaluation being participated in"}]},
      {"name":"VettingEvaluation","type":"standard","domain":"talent_recruitment","description":"Stores the status and outcome of a vetting evaluation related to an application form. Name, Outcome, Status, ApplicationFormId, and VettingType identify the application, type of vetting, progress, and result.","fields":[{"name":"Name","type":"Text","description":"Display name identifying the vetting evaluation"},{"name":"Outcome","type":"Picklist","description":"Result of the vetting: Approved, Conditionally Approved, Flagged for Review, Pending, or Rejected"},{"name":"Status","type":"Picklist","description":"Processing status: Not Started, In Progress, or Complete"},{"name":"ApplicationFormId","type":"Lookup","description":"Reference to the application form being vetted"},{"name":"VettingType","type":"Picklist","description":"Category of vetting such as Background Check, Health Examination, or Reference Check"}],"relationships":[{"target":"EmploymentOfferVettingEval","type":"parent","description":"Parent of junction records linking this vetting to employment offers"}]},
      {"name":"Examination","type":"standard","domain":"talent_recruitment","description":"Represents an authorized examination used to evaluate a person’s qualifications. Name, Description, and Status identify and describe the examination and whether it is available for use.","fields":[{"name":"Name","type":"Text","description":"Name of the examination or certification test"},{"name":"Description","type":"LongTextArea","description":"Description of what the examination covers and its requirements"},{"name":"Status","type":"Picklist","description":"Whether this examination is active and available for use"}],"relationships":[{"target":"PersonExamination","type":"parent","description":"Parent of records tracking which individuals have completed this examination"}]},
      {"name":"PersonExamination","type":"standard","domain":"talent_recruitment","description":"Records an Examination completed by a person, including its completion and result. Name, PersonId, ExaminationId, CompletionDate, and Result identify the person, examination, completion date, and recorded outcome.","fields":[{"name":"Name","type":"AutoNumber","description":"Auto-generated identifier for the person examination record"},{"name":"PersonId","type":"Lookup","description":"Reference to the person account who took the examination"},{"name":"ExaminationId","type":"Lookup","description":"Reference to the examination that was completed"},{"name":"CompletionDate","type":"Date","description":"Date when the person completed the examination"},{"name":"Result","type":"Picklist","description":"Outcome of the examination such as Pass, Fail, or Pending"}],"relationships":[{"target":"Examination","type":"lookup","description":"Links to the examination that was completed"}]},
      {"name":"CourseOffering","type":"standard","domain":"talent_recruitment","description":"Represents a scheduled instance of a training course or other course offering. Name, StartDate, EndDate, and Status capture its scheduled period and lifecycle state.","fields":[{"name":"Name","type":"Text","description":"Name or title of the course offering"},{"name":"StartDate","type":"Date","description":"Date when the course offering begins"},{"name":"EndDate","type":"Date","description":"Date when the course offering ends"},{"name":"Status","type":"Picklist","description":"Current status of the course such as Scheduled, In Progress, or Completed"}],"relationships":[{"target":"Examination","type":"lookup","description":"Links to an examination associated with this training course"}]},
      {"name":"EmploymentOffer","type":"standard","domain":"talent_recruitment","description":"Represents a tentative or final offer made for an applicant’s related Application Form. Name, Type, Status, ApplicationFormId, and OfferDate identify the offer stage, current state, application, and offer date.","fields":[{"name":"Name","type":"Text","description":"Display name or reference for the employment offer"},{"name":"Type","type":"Picklist","description":"Type of offer: Tentative or Final"},{"name":"Status","type":"Picklist","description":"Current status of the offer such as Pending, Accepted, or Declined"},{"name":"ApplicationFormId","type":"Lookup","description":"Reference to the application form this offer is based on"},{"name":"OfferDate","type":"Date","description":"Date when the employment offer was extended to the applicant"}],"relationships":[{"target":"EmploymentOfferVettingEval","type":"parent","description":"Parent of junction records linking this offer to vetting evaluation results"}]},
      {"name":"EmploymentOfferVettingEval","type":"standard","domain":"talent_recruitment","description":"Associates an EmploymentOffer with a required VettingEvaluation. Name, EmploymentOfferId, and VettingEvaluationId identify the offer and the vetting result considered before the offer is finalized.","fields":[{"name":"Name","type":"AutoNumber","description":"Auto-generated identifier for the offer-vetting junction record"},{"name":"EmploymentOfferId","type":"Lookup","description":"Reference to the employment offer"},{"name":"VettingEvaluationId","type":"Lookup","description":"Reference to the vetting evaluation linked to this offer"}],"relationships":[{"target":"EmploymentOffer","type":"lookup","description":"Links to the employment offer requiring vetting clearance"},{"target":"VettingEvaluation","type":"lookup","description":"Links to the vetting evaluation confirming applicant clearance"}]}
    ]
  },

  "agentforce": {
    "objects": [
      {"name":"ApplicationForm","type":"standard","domain":"agentforce","description":"ApplicationForm captures an application and its processing stage. Name identifies the form, Stage tracks its current stage, AccountId associates it with an account, FundingOpportunityId links it to a funding opportunity, and SubmittedDate records when it was submitted.","fields":[{"name":"Name","type":"Text","description":"Display name or reference number for the application form"},{"name":"Stage","type":"Picklist","description":"Current stage such as New, Details Validated, Evaluation Complete, Vetting Complete, Rejected, Approved, or Offered"},{"name":"AccountId","type":"Lookup","description":"Reference to the person account of the applicant"},{"name":"FundingOpportunityId","type":"Lookup","description":"Reference to the funding opportunity being applied for, if applicable"},{"name":"SubmittedDate","type":"Date","description":"Date when the application was submitted"}],"relationships":[{"target":"ApplicationFormRelation","type":"parent","description":"Parent of relation records linking participants to this application"},{"target":"ApplicationFormEvaluation","type":"parent","description":"Parent of evaluation records for reviewing this application"}]},
      {"name":"Lead","type":"standard","domain":"agentforce","description":"Lead represents a potential candidate created for recruiter outreach. FirstName, LastName, Email, and Title identify the candidate and opportunity context, while Status tracks the lead through outreach and qualification.","fields":[{"name":"FirstName","type":"Text","description":"First name of the candidate lead"},{"name":"LastName","type":"Text","description":"Last name of the candidate lead"},{"name":"Email","type":"Email","description":"Email address for outreach communications"},{"name":"Title","type":"Text","description":"Job title combining recruitment posting name and candidate name"},{"name":"Status","type":"Picklist","description":"Lead status such as New, Contacted, or Qualified"}],"relationships":[{"target":"RecruitmentPosting","type":"lookup","description":"Links to the recruitment posting this candidate lead was sourced for"}]},
      {"name":"PartyProfile","type":"standard","domain":"agentforce","description":"PartyProfile stores profile information associated with an applicant or other party. Name identifies the profile, AccountId relates it to the person account, and ProfileType categorizes the profile.","fields":[{"name":"Name","type":"Text","description":"Display name of the party profile"},{"name":"AccountId","type":"Lookup","description":"Reference to the person account this profile belongs to"},{"name":"ProfileType","type":"Picklist","description":"Type of profile such as Applicant or Employee"}],"relationships":[{"target":"PartyProfileAddress","type":"parent","description":"Parent of address records storing location preferences"},{"target":"PersonEducation","type":"parent","description":"Parent of education history records"},{"target":"PersonCompetency","type":"parent","description":"Parent of competency records tracking skills and expertise"}]},
      {"name":"PersonCompetency","type":"standard","domain":"agentforce","description":"PersonCompetency records a competency associated with a person and is used in skill-based candidate matching. Name identifies the competency record, PersonId relates it to the person, Category classifies the competency, and ProficiencyLevel records the person’s proficiency.","fields":[{"name":"Name","type":"Text","description":"Name of the competency or skill"},{"name":"PersonId","type":"Lookup","description":"Reference to the person account holding this competency"},{"name":"Category","type":"Picklist","description":"Category of competency such as Communication, Leadership, or Technical"},{"name":"ProficiencyLevel","type":"Picklist","description":"Skill proficiency level such as Beginner, Intermediate, Advanced, or Expert"}],"relationships":[{"target":"PartyProfile","type":"lookup","description":"Links to the party profile this competency belongs to"}]},
      {"name":"PartyProfileAddress","type":"standard","domain":"agentforce","description":"PartyProfileAddress stores an address related to a PartyProfile, including current and permanent applicant addresses used by recruitment flows. Name identifies the address record, PartyProfileId links it to the profile, and Street, City, State, and PostalCode capture the address.","fields":[{"name":"Name","type":"AutoNumber","description":"Auto-generated identifier for the address record"},{"name":"PartyProfileId","type":"Lookup","description":"Reference to the parent party profile"},{"name":"Street","type":"Text","description":"Street address of the applicant"},{"name":"City","type":"Text","description":"City name"},{"name":"State","type":"Text","description":"State or province"},{"name":"PostalCode","type":"Text","description":"Postal or ZIP code"}],"relationships":[{"target":"PartyProfile","type":"lookup","description":"Links to the party profile this address belongs to"}]},
      {"name":"PersonEducation","type":"standard","domain":"agentforce","description":"PersonEducation stores educational qualifications associated with a person and can be used to prefill or review job applications. Name and PersonId identify the record and person, while InstitutionName, DegreeType, and FieldOfStudy describe the educational qualification.","fields":[{"name":"Name","type":"Text","description":"Name or title of the education record"},{"name":"PersonId","type":"Lookup","description":"Reference to the person account this education record belongs to"},{"name":"InstitutionName","type":"Text","description":"Name of the educational institution"},{"name":"DegreeType","type":"Picklist","description":"Type of degree such as Bachelor, Master, or Doctorate"},{"name":"FieldOfStudy","type":"Text","description":"Major or field of study"}],"relationships":[{"target":"PartyProfile","type":"lookup","description":"Links to the party profile this education record belongs to"}]},
      {"name":"PublicComplaint","type":"standard","domain":"agentforce","description":"PublicComplaint stores a reported issue or incident for intake, review, prioritization, and possible conversion to an investigative case. Name identifies the complaint, Status tracks its progress, Description captures the reported concern, AccountId associates it with an account, and ComplaintDate records the complaint date.","fields":[{"name":"Name","type":"AutoNumber","description":"Auto-generated complaint reference number"},{"name":"Status","type":"Picklist","description":"Current status of the complaint such as New, Under Review, or Resolved"},{"name":"Description","type":"LongTextArea","description":"Detailed description of the complaint provided by the constituent"},{"name":"AccountId","type":"Lookup","description":"Reference to the person account of the complainant"},{"name":"ComplaintDate","type":"Date","description":"Date when the complaint was filed"}],"relationships":[{"target":"ComplaintCase","type":"parent","description":"Parent of complaint case records linking this complaint to investigative cases"}]}
    ]
  },

  "einstein_ai": {
    "objects": [
      {"name":"FundingDisbursement","type":"standard","domain":"einstein_ai","description":"FundingDisbursement represents a disbursement associated with a funding award and is a grounding source for Funding Award Summary. Its fields include Name, FundingAwardId, Amount, DisbursementDate, and Status, which identify the disbursement, relate it to the award, and capture its amount, date, and current status.","fields":[{"name":"Name","type":"AutoNumber","description":"Auto-generated identifier for the disbursement record"},{"name":"FundingAwardId","type":"Lookup","description":"Reference to the funding award this disbursement belongs to"},{"name":"Amount","type":"Currency","description":"The monetary amount of this disbursement"},{"name":"DisbursementDate","type":"Date","description":"Date when the disbursement was executed"},{"name":"Status","type":"Picklist","description":"Status of the disbursement such as Scheduled, Completed, or Cancelled"}],"relationships":[{"target":"FundingAward","type":"lookup","description":"Links to the funding award this disbursement is part of"}]},
      {"name":"InteractionSummary","type":"standard","domain":"einstein_ai","description":"InteractionSummary stores interaction notes that can ground Notes Summary and provide users with a record of constituent or case-participant interactions. Its fields include Name, SummaryContent, InteractionDate, IsPublished, and ParentRecordId; publishing an interaction note locks the related interaction summary against further edits.","fields":[{"name":"Name","type":"Text","description":"Title or subject of the interaction summary"},{"name":"SummaryContent","type":"RichTextArea","description":"Rich text content of the meeting notes and interaction details"},{"name":"InteractionDate","type":"DateTime","description":"Date and time when the interaction occurred"},{"name":"IsPublished","type":"Checkbox","description":"Indicates whether the summary has been published and locked as evidence"},{"name":"ParentRecordId","type":"Lookup","description":"Reference to the parent record such as a case or care plan"}],"relationships":[{"target":"Interaction","type":"lookup","description":"Links to the parent interaction record"}]}
    ]
  },

  "data_360": {
    "objects": [
      {"name":"Individual","type":"standard","domain":"data_360","description":"Individual is used as a Data 360 data model object for individual profile data and is the target of the Individual_OrgAlias stream. Its profile fields include FirstName, LastName, ConsentStatus, and BirthDate.","fields":[{"name":"FirstName","type":"Text","description":"First name of the individual"},{"name":"LastName","type":"Text","description":"Last name of the individual"},{"name":"ConsentStatus","type":"Picklist","description":"Current data consent status for privacy compliance"},{"name":"BirthDate","type":"Date","description":"Date of birth of the individual"}],"relationships":[{"target":"Account","type":"lookup","description":"Links to the account record for this individual"},{"target":"Contact","type":"lookup","description":"Links to the contact record for this individual"}]},
      {"name":"Account","type":"standard","domain":"data_360","description":"Account represents account data ingested from Public Sector Solutions and is mapped by Account_OrgAlias to the Account and Party data model objects. Its fields include Name, Type, BillingCity, and BillingState.","fields":[{"name":"Name","type":"Text","description":"Name of the account or organization"},{"name":"Type","type":"Picklist","description":"Account type such as Person Account, Business, or Agency"},{"name":"BillingCity","type":"Text","description":"City of the account's billing address"},{"name":"BillingState","type":"Text","description":"State of the account's billing address"}],"relationships":[{"target":"Contact","type":"parent","description":"Parent of contacts associated with this account"},{"target":"Individual","type":"lookup","description":"Links to the individual record for data privacy management"}]},
      {"name":"Contact","type":"standard","domain":"data_360","description":"Contact represents constituent or other contact data and is mapped by Contact_OrgAlias to AccountContact, Individual, and Party. Its fields include FirstName, LastName, Email, and AccountId.","fields":[{"name":"FirstName","type":"Text","description":"First name of the contact"},{"name":"LastName","type":"Text","description":"Last name of the contact"},{"name":"Email","type":"Email","description":"Email address of the contact"},{"name":"AccountId","type":"Lookup","description":"Reference to the parent account"}],"relationships":[{"target":"Account","type":"lookup","description":"Links to the parent account this contact belongs to"},{"target":"Individual","type":"lookup","description":"Links to the individual record for privacy management"}]}
    ]
  },

  "experience_cloud": {
    "objects": [
      {"name":"CarePlan","type":"standard","domain":"experience_cloud","description":"CarePlan represents an individualized plan used to coordinate goals, benefits, services, and actions for a constituent. Name identifies the plan, AccountId associates it with the constituent account, Status tracks its state, and StartDate and EndDate define the plan period.","fields":[{"name":"Name","type":"Text","description":"Display name of the care plan"},{"name":"AccountId","type":"Lookup","description":"Reference to the person account this care plan belongs to"},{"name":"Status","type":"Picklist","description":"Current status of the care plan such as Active, On Hold, or Completed"},{"name":"StartDate","type":"Date","description":"Date when the care plan became active"},{"name":"EndDate","type":"Date","description":"Expected or actual end date of the care plan"}],"relationships":[{"target":"Referral","type":"parent","description":"Parent of referral records for service provider coordination"}]},
      {"name":"Referral","type":"standard","domain":"experience_cloud","description":"Referral records a request to connect a constituent with a provider or another agency for services. Name identifies the referral, Status tracks its progress, ReferralType classifies it, AccountId identifies the constituent account, and ProviderId associates the selected provider.","fields":[{"name":"Name","type":"AutoNumber","description":"Auto-generated referral reference number"},{"name":"Status","type":"Picklist","description":"Current status of the referral such as Pending, Accepted, In Progress, or Completed"},{"name":"ReferralType","type":"Picklist","description":"Category of referral such as Medical, Social Services, or Housing"},{"name":"AccountId","type":"Lookup","description":"Reference to the constituent's account"},{"name":"ProviderId","type":"Lookup","description":"Reference to the service provider receiving the referral"}],"relationships":[{"target":"CarePlan","type":"lookup","description":"Links to the care plan this referral supports"}]}
    ]
  },

  "crm_analytics": {
    "objects": [
      {"name":"Case","type":"standard","domain":"crm_analytics","description":"Case supplies case-level operational data for workload and processing-time analytics in Public Sector Solutions. CaseNumber identifies the case, while Status, Priority, OwnerId, CreatedDate, and ClosedDate support analysis of ownership, workload, urgency, status duration, and overall processing time.","fields":[{"name":"CaseNumber","type":"AutoNumber","description":"Auto-generated unique case reference number"},{"name":"Status","type":"Picklist","description":"Current status of the case such as New, In Progress, Escalated, or Closed"},{"name":"Priority","type":"Picklist","description":"Priority level such as High, Medium, or Low"},{"name":"OwnerId","type":"Lookup","description":"Reference to the user or queue assigned to this case"},{"name":"CreatedDate","type":"DateTime","description":"Date and time when the case was created"},{"name":"ClosedDate","type":"DateTime","description":"Date and time when the case was closed"}],"relationships":[{"target":"Account","type":"lookup","description":"Links to the account this case belongs to"},{"target":"Contact","type":"lookup","description":"Links to the contact who reported or is associated with this case"}]}
    ]
  },

  "emergency_and_assets": {
    "objects": [
      {"name":"Polygon","type":"standard","domain":"emergency_and_assets","description":"Defines a geographic boundary for emergency zones, restricted areas, and inspection regions. Polygons are used to map affected areas during crises, coordinate field responders across multiple locations, and establish boundaries for location-based inspection scheduling. Agencies create polygons to visually represent emergency zones on maps and track visitor access to restricted areas.","fields":[{"name":"Name","type":"Text","description":"Display name of the geographic boundary or zone"},{"name":"Description","type":"LongTextArea","description":"Description of the polygon's purpose and the area it covers"},{"name":"Status","type":"Picklist","description":"Current status such as Active, Inactive, or Archived"},{"name":"PolygonType","type":"Picklist","description":"Classification such as Emergency Zone, Restricted Area, or Inspection Region"}],"relationships":[{"target":"Visit","type":"parent","description":"Parent of visit records for inspections and emergency operations within this zone"}]},
      {"name":"Visit","type":"standard","domain":"emergency_and_assets","description":"Represents an on-site visit for emergency inspections, resource delivery, or compliance verification within emergency zones. After emergency permits are approved, inspectors use the mobile Inspection app to verify site compliance with local health and safety ordinances. Visit records track the location, timing, and outcomes of emergency field operations.","fields":[{"name":"Name","type":"AutoNumber","description":"Auto-generated visit reference number"},{"name":"Status","type":"Picklist","description":"Visit status such as Planned, In Progress, Completed, or Cancelled"},{"name":"VisitDate","type":"DateTime","description":"Scheduled or actual date and time of the visit"},{"name":"AccountId","type":"Lookup","description":"Reference to the account or location being visited"},{"name":"PolygonId","type":"Lookup","description":"Reference to the geographic zone this visit is within"}],"relationships":[{"target":"Polygon","type":"lookup","description":"Links to the emergency zone or geographic boundary"},{"target":"Visitor","type":"parent","description":"Parent of visitor records tracking personnel at this site"}]},
      {"name":"Visitor","type":"standard","domain":"emergency_and_assets","description":"Tracks a person visiting a site for emergency operations, inspections, or resource distribution. Visitor records manage access to restricted areas during emergencies, track inspector assignments to specific sites, and coordinate field responder deployments across multiple locations.","fields":[{"name":"Name","type":"Text","description":"Name of the visitor or field responder"},{"name":"VisitId","type":"Lookup","description":"Reference to the visit this person is associated with"},{"name":"VisitorType","type":"Picklist","description":"Type of visitor such as Inspector, Responder, or Constituent"},{"name":"CheckInTime","type":"DateTime","description":"Time when the visitor checked in at the site"},{"name":"Address","type":"Text","description":"Address associated with the visitor"}],"relationships":[{"target":"Visit","type":"lookup","description":"Links to the visit this person is associated with"}]}
    ]
  },

  "employee_experience": {
    "objects": [
      {"name":"Employee2","type":"standard","domain":"employee_experience","description":"Employee2 represents an employee and stores identifying and organizational details through fields such as Name, EmployeeNumber, Status, DepartmentName, and HireDate. The Create Employee screen flow creates an employee record together with related person account and contact records, and the record can be linked to the employee's platform user through UserId.","fields":[{"name":"Name","type":"Text","description":"Full name of the employee"},{"name":"EmployeeNumber","type":"Text","description":"Unique employee identifier within the agency"},{"name":"Status","type":"Picklist","description":"Current employment status such as Active, On Leave, or Terminated"},{"name":"DepartmentName","type":"Text","description":"Name of the department the employee belongs to"},{"name":"HireDate","type":"Date","description":"Date when the employee was hired"}],"relationships":[{"target":"Employment","type":"parent","description":"Parent of employment records capturing role and schedule details"},{"target":"PersonEmployment","type":"parent","description":"Parent of person employment records linking to work experience"}]},
      {"name":"Employment","type":"standard","domain":"employee_experience","description":"Employment captures an employee's employment details, including Name, EmployeeId, EmploymentType, ScheduleType, Status, and StartDate. Supported example values include Contractors, Civilian Employee, and Military Employee for Employment Type; Full-time and Part-time for Schedule Type; and Active, Resigned, and Terminated for Status. HR specialists create an employment record by selecting Employments and clicking New, then selecting the employee and entering the applicable details.","fields":[{"name":"Name","type":"Text","description":"Display name or reference for the employment record"},{"name":"EmployeeId","type":"Lookup","description":"Reference to the Employee2 record"},{"name":"EmploymentType","type":"Picklist","description":"Type of employment: Contractors, Civilian Employee, or Military Employee"},{"name":"ScheduleType","type":"Picklist","description":"Work schedule: Full-time or Part-time"},{"name":"Status","type":"Picklist","description":"Employment status: Active, Resigned, or Terminated"},{"name":"StartDate","type":"Date","description":"Date when the employment began"}],"relationships":[{"target":"Employee2","type":"lookup","description":"Links to the employee record this employment belongs to"}]},
      {"name":"PersonEmployment","type":"standard","domain":"employee_experience","description":"PersonEmployment stores a person's work experience through fields such as Name, PersonId, EmployerName, JobTitle, StartDate, and EndDate, and the data model supports its relationship with Employee2. Applicant profile and job application guided flows capture prior employment details in PersonEmployment records and use those records to prefill work-experience information for returning applicants. Employee access to these Talent Recruitment Management workflows is provided through Talent Recruitment Management Employee Access or Talent Recruitment Management Hiring Manager Access rather than the Employee_Experience_User permission set group.","fields":[{"name":"Name","type":"Text","description":"Display name for the person employment record"},{"name":"PersonId","type":"Lookup","description":"Reference to the person account"},{"name":"EmployerName","type":"Text","description":"Name of the employer or organization"},{"name":"JobTitle","type":"Text","description":"Title of the position held"},{"name":"StartDate","type":"Date","description":"Start date of this employment"},{"name":"EndDate","type":"Date","description":"End date of this employment, blank if current"}],"relationships":[{"target":"Employee2","type":"lookup","description":"Links to the employee record if this person is a current employee"}]}
    ]
  },

  "grantmaking": {
    "objects": [
      {"name":"FundingOpportunity","type":"standard","domain":"grantmaking","description":"Represents a grant funding opportunity that grantmakers create and manage in Public Sector Solutions. It stores the opportunity name, description, application instructions, budget template, status, and total funding amount presented to prospective applicants.","fields":[{"name":"Name","type":"Text","description":"Title of the funding opportunity"},{"name":"Description","type":"RichTextArea","description":"Detailed description of the funding opportunity and eligibility criteria"},{"name":"ApplicationInstructions","type":"RichTextArea","description":"Instructions for applicants on how to apply"},{"name":"BudgetTemplateId","type":"Lookup","description":"Reference to the budget template for applicant budget proposals"},{"name":"Status","type":"Picklist","description":"Publication status such as Draft, Published, or Closed"},{"name":"TotalFundingAmount","type":"Currency","description":"Total amount of funding available through this opportunity"}],"relationships":[{"target":"ApplicationForm","type":"parent","description":"Parent of application form records submitted by grant seekers"},{"target":"FundingAward","type":"parent","description":"Parent of funding awards granted through this opportunity"},{"target":"Budget","type":"lookup","description":"Links to the budget template for this funding opportunity"}]},
      {"name":"FundingAward","type":"standard","domain":"grantmaking","description":"Represents grant funding awarded from a Funding Opportunity. It records the awarded amount, contract start and end dates, status, and associated Budget for administering the award.","fields":[{"name":"Name","type":"Text","description":"Display name or reference for the funding award"},{"name":"FundingOpportunityId","type":"Lookup","description":"Reference to the funding opportunity this award was granted from"},{"name":"Amount","type":"Currency","description":"Total monetary amount awarded"},{"name":"ContractStartDate","type":"Date","description":"Start date of the award contract timeframe"},{"name":"ContractEndDate","type":"Date","description":"End date of the award contract timeframe"},{"name":"Status","type":"Picklist","description":"Current status of the award such as Active, Completed, or Amended"},{"name":"BudgetId","type":"Lookup","description":"Reference to the budget tracking how funds are spent"}],"relationships":[{"target":"FundingOpportunity","type":"lookup","description":"Links to the funding opportunity this award was granted from"},{"target":"FundingAwardRequirement","type":"parent","description":"Parent of requirement records defining milestones and deliverables"},{"target":"FundingDisbursement","type":"parent","description":"Parent of disbursement records tracking payment execution"},{"target":"Budget","type":"lookup","description":"Links to the budget tracking expenditures for this award"}]},
      {"name":"FundingAwardRequirement","type":"standard","domain":"grantmaking","description":"Represents a scheduled obligation associated with a Funding Award. It records the requirement name, type, scheduled date, and status and can be used for recurring award requirements.","fields":[{"name":"Name","type":"Text","description":"Name or title of the requirement"},{"name":"FundingAwardId","type":"Lookup","description":"Reference to the parent funding award"},{"name":"ScheduledDate","type":"Date","description":"Due date for this requirement"},{"name":"Status","type":"Picklist","description":"Completion status such as Pending, Submitted, Approved, or Overdue"},{"name":"RequirementType","type":"Picklist","description":"Type of requirement such as Financial Report, Progress Report, or Final Report"}],"relationships":[{"target":"FundingAward","type":"lookup","description":"Links to the funding award this requirement belongs to"}]},
      {"name":"Budget","type":"standard","domain":"grantmaking","description":"Represents a grant budget with an amount, applicable start and end dates, status, and related Funding Opportunity. Budget records support budget proposals, allocation management, and spending tracking.","fields":[{"name":"Name","type":"Text","description":"Display name of the budget"},{"name":"Amount","type":"Currency","description":"Total budget amount"},{"name":"StartDate","type":"Date","description":"Start date of the budget period"},{"name":"EndDate","type":"Date","description":"End date of the budget period"},{"name":"Status","type":"Picklist","description":"Current state such as Planning, Submitted, or Approved"},{"name":"FundingOpportunityId","type":"Lookup","description":"Reference to the funding opportunity this budget is associated with"}],"relationships":[{"target":"FundingOpportunity","type":"lookup","description":"Links to the funding opportunity this budget template belongs to"},{"target":"BudgetAllocation","type":"parent","description":"Parent of allocation records tracking actual expenditures"},{"target":"FundingAward","type":"parent","description":"Parent of funding awards using this budget for expenditure tracking"}]},
      {"name":"BudgetAllocation","type":"standard","domain":"grantmaking","description":"Represents an amount allocated within a Budget. Each allocation identifies its amount and the category and period names used to organize the budget.","fields":[{"name":"Name","type":"AutoNumber","description":"Auto-generated identifier for the budget allocation"},{"name":"BudgetId","type":"Lookup","description":"Reference to the parent budget"},{"name":"Amount","type":"Currency","description":"Actual amount spent for this allocation"},{"name":"CategoryName","type":"Text","description":"Budget category this allocation belongs to such as Personnel or Supplies"},{"name":"PeriodName","type":"Text","description":"Budget period this allocation covers such as Q1 or Q2"}],"relationships":[{"target":"Budget","type":"lookup","description":"Links to the parent budget this allocation tracks spending against"}]},
      {"name":"ApplicationFormEvaluation","type":"standard","domain":"grantmaking","description":"Represents a review of an application form by an assigned reviewer. It records the reviewer's decision, rating, and comments for use in the grant application evaluation process.","fields":[{"name":"Name","type":"AutoNumber","description":"Auto-generated identifier for the evaluation"},{"name":"ApplicationFormId","type":"Lookup","description":"Reference to the application form being evaluated"},{"name":"ReviewerId","type":"Lookup","description":"Reference to the user or contact performing the review"},{"name":"Decision","type":"Picklist","description":"Reviewer's decision such as Approve or Reject"},{"name":"Rating","type":"Number","description":"Numerical rating assigned by the reviewer"},{"name":"Comments","type":"LongTextArea","description":"Reviewer's written feedback and notes"}],"relationships":[{"target":"ApplicationForm","type":"lookup","description":"Links to the application form being evaluated"},{"target":"ApplicationFormEvalPtcp","type":"parent","description":"Parent of participant records tracking who is involved in this evaluation"}]},
      {"name":"PaymentRequest","type":"standard","domain":"grantmaking","description":"Represents a request that can be used as a source record for outbound-payment processing. When an approved Payment Request meets configured criteria, a record-triggered flow can generate a payment instruction for processing by an external finance system.","fields":[{"name":"Name","type":"AutoNumber","description":"Auto-generated identifier for the payment request"},{"name":"FundingAwardId","type":"Lookup","description":"Reference to the funding award this payment request belongs to"},{"name":"Amount","type":"Currency","description":"Total amount requested for disbursement"},{"name":"RequestDate","type":"Date","description":"Date when the payment request was submitted"},{"name":"Status","type":"Picklist","description":"Processing status such as Submitted, Approved, Paid, or Rejected"}],"relationships":[{"target":"FundingAward","type":"lookup","description":"Links to the funding award this payment request is drawn from"},{"target":"PaymentRequestLine","type":"parent","description":"Parent of line item records breaking down the payment by category"}]},
      {"name":"PaymentRequestLine","type":"standard","domain":"grantmaking","description":"Represents a line associated with a Payment Request. It records the line amount, category name, and description while linking the line to its parent request.","fields":[{"name":"Name","type":"AutoNumber","description":"Auto-generated identifier for the payment request line"},{"name":"PaymentRequestId","type":"Lookup","description":"Reference to the parent payment request"},{"name":"Amount","type":"Currency","description":"Amount for this line item"},{"name":"CategoryName","type":"Text","description":"Budget category this line item belongs to"},{"name":"Description","type":"Text","description":"Description of the expense or purpose of this line item"}],"relationships":[{"target":"PaymentRequest","type":"lookup","description":"Links to the parent payment request this line item belongs to"}]}
    ]
  }

};
